window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_029"]={"n":"周之琦","dyn":"清","poems":[{"t":"移居日偶得小诗 其一","f":"七言绝句","c":["旧宅移来柳一枝，连番膏雨助生机。","可能身作桓宣武，看得腰支到十围。"]},{"t":"移居日偶得小诗 其二","f":"七言绝句","c":["一珠柽柳两分身，移植南墙便隔邻。","根到重泉会相见，未应忘是一家春。"]},{"t":"移居日偶得小诗 其三","f":"七言绝句","c":["棠梨今后为谁开，也许移根别院栽。","盼得明年花信早，春风来似故人来。"]},{"t":"移居日偶得小诗 其四","f":"七言绝句","c":["狭巷萧条隔市尘，泥涂往往欲摧轮。","平津莫讶回车早，此地曾无牧豕人。"]},{"t":"移居日偶得小诗 其五","f":"七言绝句","c":["膏环粔籹贺堂成，几日新邻便有情。","谁说海鸥心迹异，两无虞诈不须盟。"]},{"t":"临江仙","f":"古风","c":["一架藤阴留不得，珠巢无处寻踪。","绣衣著了抗尘容。","向来殊落落，此别转匆匆。","十载长安多胜侣，频番酒绿灯红。","而今心事更谁同。","秋怀纨扇月，春梦玉柯风。"]},{"t":"瑞鹤仙 忆京寓藤花作","f":"古风","c":["晓寒欺绣幕。","过啼鴂光阴，离愁萧索。","新词寄归鹤。","奈书传阆苑，信音辽邈。","纤枝翠络。","料此际、垂垂绽萼。","尽飘零、客燕天涯，长忆紫茸檐角。","兰杓。","浮红泛绿，摘艳吟香，与花同酌。","华胥梦觉。","赏心事，忍抛却。","想闲庭多少，游蜂戏蝶，未肯襟期漫托。","但年年、吹冷东风，自开自落。"]},{"t":"永遇乐 其一 成都武候祠","f":"古风","c":["天设岩疆，井蛙亡后，形胜谁据。","半壁经营，两朝开济，再世生伊吕。","炎灵邈矣，讴思未沫，长诵大名千古。","任辛毗、军门仗节，笑他畏蜀如虎。","星芒骤落，降笺草草，拱手河山输与。","邺下称尊，江东并列，史笔吾无取。","锦官城外，云车风马，想像翠华来处。","凭君看、荒陵咫尺，尚留汉土。"]},{"t":"永遇乐 其二 成都贡院伪蜀故宫也，壬午从事秋闱作","f":"古风","c":["棘院风清，桂轮香满，仙驭初驻。","射策人来，翘材馆启，旧是朝天路。","南轩史笔，东阳诗草，恰在紫云深处。","话兴亡、煎茶漏永，待添画烛重赋。","王颠孟蹶，轻尘短晷，梦影相看何许。","城上芙蓉，宫中花蕊，不管人西顾。","宣华小苑，摩诃芳径，多少断垣荒础。","今犹幸、文昌朗耀，粉廊快睹。"]},{"t":"永遇乐 其三 风雪渡江宿九江通远驿","f":"古风","c":["退鹢风颠，呿鲸浪涌，帆叶掀舞。","宦海沈浮，迷津指点，漫唱公无渡。","凉秋暗雨，残冬密雪，荏苒岁华成故。","想山中、匡君笑客，往来浪迹良苦。","邮亭梦里，烟波东望，忍见寒潮生处。","帘幕轻阴，琴歌欢意，聊共灯唇语。","悠悠絮影，依依兰膳，且喜早梅香吐。","归期近、庭前定有，鹊声报午。"]},{"t":"木兰花慢 支机石","f":"古风","c":["笋舆寻胜赏，讶神物、寄烟寰。","想槎客携归，星娥赠与，仙骨珊珊。","斓斑。","艳称蜀锦，问七襄何似五云端。","幻迹谁云可转，灵心好在无言。","禅关。","尚识孱颜。","清露湿、翠屏闲。","但怅望、吹笙迟回弄杼，梦冷银湾。","相看。","绛霄路迥，叹红尘沦谪几时还。","回首珠宫玉宇，凄凉天上人间。"]},{"t":"陌上花 薛涛井","f":"古风","c":["高唐梦后朝云，留下楚台遗韵。","一曲琴心，容易翠翘偷近。","玉蝉金雀嬉游处，千古风流无尽。","赋闲情、况有巴笺十色，待题幽恨。","向回栏、更倚瓶沈信杳，且喜银床堪认。","照影婵娟，谁似扫眉人俊。","枇杷花落闲门闭，冶思空传兰讯。","锦江春、付与楼阴修竹，几堆香粉。"]},{"t":"玉漏迟 其一 夜话尹竹农同年署斋","f":"古风","c":["夜寒莲漏悄。","纹疏静掩，铜荷低照。","迅羽光阴，心事漫传青鸟。","梦里长安片月，更愁里、天涯芳草。","还自恼。","云窗雾阁，庾尘谁扫。","何处唤酒银釭，听小管清声，素弦凄调。","艳冶追寻，争似寸笺吟好。","计日东风破冷，又相对、春山一笑。","芳信早。","梅花几枝开了。"]},{"t":"玉漏迟 其二 秋夜对月偶忆少陵\"斫却月中桂，清光应更多\"之语，因写其意","f":"古风","c":["碧空圆镜展。","无端幻出，交柯零乱。","望里阴阴，占却广寒庭院。","自倚阎浮树影，怎禁得、吴郎偷眼。","尘雾卷。","丁丁玉斧，等闲飘散。","遥睇露脚斜飞，似坠叶霜林，峭风轻剪。","唤作天香，终是药娥愁见。","记否王孙去久，且归咏、淮南秋怨。","清漏转。","霓裳旧歌重按。"]},{"t":"玉漏迟 其三 高巳生、钱充泉、王远闻同舟，相送信宿去严陵道中却寄","f":"古风","c":["片帆人万里。","琴歌兴在，仍搴吟袂。","过雨秋容，侵晓越娥妆洗。","漫拟西湖镜影，也休认、南屏烟翠。","还信未。","桐江一路，好山如此。","三载惯约清游，叹饮渌题花，顿成前事。","醉拍征衫，空惜酒痕红渍。","旧垒芹泥换尽，更谁识、归舟天际。","兰棹倚。","魂消画眉声里。"]},{"t":"霜叶飞 伯兄之戚已更岁矣，笏侄自粤归汴，由汴来蜀，泫然赋此","f":"古风","c":["素冠衔涕，重相见，伤心尘面憔悴。","去年轻趁片帆风，送箭波长逝。","甚浃月、珠江戾止。","无端啼湿春鹃泪。","但爱日庭前，且幸得、孤雏侍侧，馨膳聊慰。","追念妙墨渊云，香名早饮，共说平步千里。","盛筵烧尾只须臾，奈镜蓉空萎。","叹寂寂乡园梦里，郊祁忍更论前事。","听雁声、哀弦外，只影天涯，断魂谁倚。"]},{"t":"祝英台近","f":"古风","c":["选佳辰，携俊侣，重问草堂路。","红萼无言，春色已如许。","相看萝幌低垂，蕙烟轻飏，忽省忆、皇华人语。","浣花句。","同是沦落天涯，应教侍尊俎。","团扇家家，不少瓣香处。","须令翠羽声中，寒泉一盏，但遥指、城南韦杜。"]},{"t":"鹧鸪天 绵州道中","f":"古风","c":["五见樱桃梦欲阑。","蚕丛容易片云还。","飞凫已觉天衢近，归骑安知蜀道难。","凉意浃，露痕乾。","不辞侵晓跨征鞍。","轻衫小扇绵州路，瓦鼓听歌豆子山。"]},{"t":"夜半乐 夜趋剑阁，中途大雷雨侵，晨始抵宿处","f":"古风","c":["暮天畏景将下，轻阴城郭，催唤雕鞍去。","到万笏尖峰，晚凉佳处。","坏云渐展，狂飙骤发，片时丹嶂冥迷，绛河倾注。","更迎面、砰轰震雷鼓。","闇中磴道曲折，蚁磨惊旋，马蹄愁误。","怕小小、篮舆山灵留住。","乱流趋壑，崩厓转石，一肩稳载吟魂，等闲偷度。","哓钟外、羊肠忍回顾。","卧想今夕，犯险虚劳，快心终阻。","行不得、空惭鹧鸪语。","耐炎曦、休恨汗湿齐纨缕。","还偻指、几日消烦暑。","邵平瓜买青门路。"]},{"t":"天香 留候祠在紫柏山下，泉皆穿地而出，盘花旋竹，泠泠有声，秦栈中佳境也","f":"古风","c":["石罅跳珠，墙阴漱玉，虚堂半枕湍濑。","倦客栖迟，征途热恼，顿觉凉生襟带。","螺鬟秀倚，想上有、餐霞人在。","几阵天风细响，吹将凤笙仙籁。","留封旧游未改。","寄冥鸿、渺然尘外。","来往赤松栖处，片云无碍。","好约他年借榻。","待尽启、轩窗面苍霭。","万叠烟岚，芝英试采。"]},{"t":"高阳台 其一 汉茂陵","f":"古风","c":["宛马吟愁，粤鸡啼恨，流虹休问猗兰。","丹鼎龙归，一丘空指苍烟。","蒲轮正好贤良聚，奈褰裳、海上仙山。","甚蓬莱，误了阿房，重误甘泉。","神君帐里知何语，但返魂香烬，枉赋哀蝉。","五柞鹃声，负他桃熟千年。","谁论朱鸟窗中事，剩初明、泪洒通天。","最难禁，玉椀凄凉，宛在人间。"]},{"t":"高阳台 其二 灞河阻涨","f":"古风","c":["雪浪翻空，银涛拍岸，柳阴不解兰舟。","顾影骄骢，几回踠足临流。","倦怀桑下贪三宿，况关心、丽玉箜篌。","慰离情，一水盈盈，多幸天留。","寻诗待赴旗亭约，奈黄梅暗雨，懒试清游。","香润红绡，从看纨扇都收。","消魂桥上西风早，怕明朝、吹换凉秋。","望京华，芳草天涯，何处高楼。"]},{"t":"高阳台 其三 平定州妒女祠事与刘伯玉妻妒妇津相类，戏拈此解","f":"古风","c":["偕隐曾传，潜渊妄托，休猜绵上娉婷。","十笏荒祠，凝尘谁扫朱棂。","春松秋菊东阿赋，问宓妃、甚事干卿。","枉思量，罗袜凌波，翠羽扬灵。","千年梦雨空飘瓦，怪胥涛遗恨，历劫难平。","唤渡蛾眉，等闲风浪还生。","茂宏九锡徒相笑，怕短辕、到此须惊。","赛村巫，一勺椒浆，好荐鸧鹒。"]},{"t":"月华清 其一 骊山温泉","f":"古风","c":["椒殿含春，兰汤试暖，华清鸾驭曾迓。","一掬鸳波，还见粉云吹麝。","倚丹台、金屋装成，漱灵液、仙源流下。","罗帕。","待凝脂净拭，翠蛾重画。","妙舞霓裳未罢。","甚咫尺延秋，夜乌啼乍。","水上黄虬，容易倩魂惊化。","访前尘、香泽仍留，诉长恨、哀湍空泻。","愁惹。","付宫花红处，白头闲话。"]},{"t":"月华清 其二 题成兰生太守西湖镜影图照","f":"古风","c":["空翠分烟，秋痕蘸水，芦湾篷背低亚。","照影盟心，恰好镜澜堪借。","向回汀、蓦地寻来，倚柔舻、消然歌罢。","吟社。","唤香山玉局，紫鸾飞下。","我亦幽怀暗写。","听灵苑清钟，旧欢都谢。","修竹祠荒，争得澹妆人迓。","待安排、画鹢闲身，尽消领、冷鸥情话。","休暇。","奈文书遮眼，漏沈遥夜。"]},{"t":"探芳信 其一 茶憩敷水驿，香山诗所谓\"上得篮辇未能去。春风敷水店门前\"者也","f":"古风","c":["晓莺唤。","似陌上柔桑，秦筝弹怨。","想画楼初日，芳魂定馀恋。","素波不照婵娟影，遗恨天涯远。","遣羁愁、艳质难留，好山还见。","依约翠眉展。","尚仿佛城南，那时人面。","秀倚东风，露华映、黛痕浅。","玉莲花色春如笑，任著帩头看。","店门前、怪底篮舆去缓。"]},{"t":"探芳信 其二","f":"古风","c":["绛霄近。","借寸晷馀闲，游踪重认。","向紫云深处，陶然翠觞引。","上清判袂仙缘在，尚有餐芝分。","倚筼屏、酒晕香凝，月轮心印。","欢极泪还忍。","念旧侣星稀，逝波空迅。","梦冷江花，但赢得、夜台恨。","百年身世浮鸥影，懒更笺天问。","楚魂招、枉付牙琴怨轸。"]},{"t":"夏初临 雨行蒲州道中有忆","f":"古风","c":["润裛鞭丝，冷侵衣袂，条山吹雨冥冥。","才过梅黄，千林点滴秋声。","客怀已是凄清。","况征途、流潦纵横。","风陵回首，莲峰翠鬟，犹隐云屏。","飞蓬自去，倚竹仍留，小窗絮语，灯火青荧。","荷花桂子，人间何处西泠。","短堠长亭。","数邮奁、听彻兰更。","泪痕凝。","钱江到时，看取吴绫。"]},{"t":"望海潮 韩信岭","f":"古风","c":["行山回合，汾河萦带，遗基尚说韩侯。","衰柳将坛，闲花战垒，千年姓字长留。","阳夏事悠然，叹黥彭一例，钟室埋愁。","震主功高，鼎分空忆蒯通谋。","征途访古停辀，望灵风天半，英气凌秋。","传檄片言，藏弓末路，荣枯总付东流。","祠宇倚津楼，想巫弦社鼓，夜夜神游。","看取长陵断褐，谁与酹荒丘。"]},{"t":"还京乐 丙戍小住都门，匆匆脂辖，怅然有作","f":"古风","c":["凤城路，习见依依巷陌如故里。","趁絮泥消尽，任教日访，琴尊欢事。","望旧巢天际。","金莲对烛光生蕊。","禁漏短，争许袖惹，蓬莱云气。","向槐堂里。","又朋簪清话，依然树色浮空，人影在地。","芳踪梦蝶重寻，幸秦源、暗通尘世。","倚征鞍、嗟倦羽飞回，游骢唤起。","好属卢沟月，须令佳会常继。"]},{"t":"扬州慢 维扬晚泊","f":"古风","c":["白纻人归，玉箫声换，短篷谁按红牙。","渐邗沟月影，又透入窗纱。","听一杵、清钟唤梦，鬓丝禅榻，休问烟花。","正羁愁、撩乱可堪，尊酒消他。","锦帆在否，算垂杨、曾见繁华。","叹画鹢春波，流萤故苑，何处人家。","殿脚翠螺抛尽，西风外、冷落宫斜。","话兴亡遗事，伤心空付栖鸦。"]},{"t":"念奴娇","f":"古风","c":["翠尊芳约，尽西清、当日鸣珂仙侣。","五载分张今更合，宛尔柯亭联步。","语燕催程，闲鸥唤客，便好挐舟去。","湖楼遥指，小栏红湿疏雨。","堪羡昆阆归来，横塘卜筑，妙得沧浪趣。","稚柳娇莺门巷接，最是金阊佳处。","波软风柔，酒浓歌脆，准拟从君住。","明朝相望，片帆空隔烟浦。"]},{"t":"夜合花 蔼人有看花之约，余乘风便已解维矣","f":"古风","c":["洛水明珠，巫峰仙佩，未如越网千丝。","绿悭顾曲，输君暖玉偷携。","青缆解，画船移。","怪津亭、折柬来迟。","向虹桥去，箫吹夜月，谁唱新词。","西湖西子归时。","长记缃裙染翰，罗帕题诗。","吟香试茗，依然闷倚空卮。","红袖冷，翠眉低。","甚好风、偏妒芳期。","倩卢家燕，闲将此恨，说与教知。"]},{"t":"二郎神 晚泊吴江，风景清旷，灯下漫填此阕，却寄吴、董、贺三同年","f":"古风","c":["乱鸦送日，傍暮霭、片帆初卸。","正小阁衔杯，纹窗剪烛，好句云笺共写。","暗里吴波催人去，早梦落、松陵桥下。","怜酒晕未消，吟边犹记，夜阑情话。","潇洒。","枫江骋望，水天如画。","认素袜明珰、词仙游处，还见秋容澹雅。","葭浦烟凉，蓼汀风细，娥月渐窥篷罅。","凭过雁、为说寒山此际，晚钟敲罢。"]},{"t":"月中桂 吴淞舟中","f":"古风","c":["思渺吴天，坐空明翠奁，稳泛秋色。","柔波荡晚，渐白蘋风细，轻寒吹入。","小红今在否。","记夜舫、新歌按拍。","迤逦垂虹路，清萧雅韵，鸥鹭定曾识。","沈吟季鹰当日。","恋莼鲈味好，归棹重觅。","溪山画里，算绵屏深处，何人消得。","扣舷招隐士，倩相送、长桥过客。","黯黯南云去，宵来为君乡梦积。"]},{"t":"巫山一段云 西湖花神廊仅余塑像二侧倚败壁间，而神采奕奕如生，命僧移置楼下并纪以词","f":"古风","c":["梦雨荒祠暗，秾华往事空。","小楼珍重避西风。","好与护芳容。","春色应无价，情缘倘再逢。","欲求粉本貌惊鸿。","看取曲栏中。"]},{"t":"眼儿媚 其一","f":"古风","c":["南朝驻跸爱杭州。","直为圣湖留。","十三门外，十三椄畔，占尽风流。","一声白雁繁华去，往事总悠悠。","刘家娘子，杨家妹子，无限春愁。"]},{"t":"眼儿媚 其二","f":"古风","c":["小船平底曲栏干。","人在画图间。","雨湖也好，晴湖也好，消得身闲。","净慈灵隐三天竺，重叠献珠幡。","千灯万佛，莲台高处，长是无言。"]},{"t":"惜红衣 访姜白石葬处","f":"古风","c":["汉渚羁愁，苕溪浪迹，野云谁识。","旧说西塍，吟魂寄幽宅。","斜阳蔓草，空怅望、春风词笔。","悽忆。","香暗影疏，掩梅花仙魄。","漂零楚客，抔土长留，湖山恣游历。","繁华梦去，故国已无觅。","好属小红珠泪，莫向冷枫啼湿。","怕洞箫清怨，吹咽六陵秋色。"]},{"t":"一落索","f":"古风","c":["山色空濛初过雨。","画船几许。","倚栏人影不分明，两桨掠、柔波去。","回首六桥烟树。","依依日暮。","更教谁与觅词仙，荡一点、春心处。"]},{"t":"夜游宫 偕董琴南、费新桥两同年泛舟西湖，时琴南赴云南任，新桥亦将入都","f":"古风","c":["一棹停云乍合。","况胜赏、韶春时节。","有约逋梅须共折。","鹤巢边，冷清清，千片雪。","绿醑兰言接。","胜尺素、遥传天末。","去燕来鸿休怅别。","指心期，但相看，湖上月。"]},{"t":"归国谣 其一","f":"古风","c":["仙境阻。","洞口桃花风又雨。","可惜阮郎游处。","看花无伴侣。","几日翠阴庭户。","留春春不住。","零乱十三筝柱。","懒听金雁语。"]},{"t":"归国谣 其二","f":"古风","c":["残梦续。","浪蕊浮花看未足。","容易晓鸦声促。","泪痕销绛烛。","缸面酒鳞吹绿。","醉来歌一曲。","何事近窗修竹。","不教丹凤宿。"]},{"t":"转应曲","f":"古风","c":["无寐。","无寐。","赚得愁人如醉。","夜深珠箔谁开。","怅望青鸾未来。","来未。","来未。","心在紫兰香里。"]},{"t":"临江仙慢","f":"古风","c":["漱石枕流计，湖光绿处，山翠浓时。","庾尘外、从教静掩柴扉。","幽栖。","为门前柳，篱边菊，赋得归期。","江南路，仅莼鲈劝客，竹马牵衣。","还思。","探梅旧崦，终胜东阁追随。","便寻常、猿鹤料也忘机。","相携。","话鄂君被，湘娥瑟，怨抑谁知。","孤山去，且春阴就梦，冷语寻诗。"]},{"t":"唐多令 垂虹舟夜","f":"古风","c":["汀柳晚萧萧。","烟波十四桥。","溯西风、一叶舟摇。","秋意也如人意苦，浑瘦尽、玉虹腰。","泪点黦冰绡。","香心冷翠翘。","怨芳魂、楚些难招。","长簟竟床灯烬落，谁念我，可怜宵。"]},{"t":"声声慢 其一","f":"古风","c":["汀蒲换色，岸柳欺寒，征帆又落吴阊。","偻指萍踪，西泠草草三霜。","翩然梦回半枕，把欢游、付与斜阳。","紫霄远、想霓裳咏罢，月斧携将。","几度伤怀旧雨，况邻人怨笛，吹冷钱江。","两地离愁，知他仙佩何方。","蓉城倩谁寄语，道尘寰、有客相望。","雁去也，秣陵书、一例断肠。"]},{"t":"声声慢 其二 偶检旧簏，得刘芙初词笺有云\"更天际阑干，断无人处，撩上几丝柳\"为之参叹","f":"古风","c":["香残镂管，泪浥琼笺，无端梦醒槐柯。","少别千年，匆匆岁月飞梭。","柳丝断魂在否，漫凄凉、拥鼻吟哦。","凝望久，只栏干天际，遥隔云波。","忆昔东华游倦，几留欢绛蜡，买醉红螺。","恨入骚辞，依然兰畹愁多。","而今玉楼赋就，比人间哀乐如何。","子夜曲，但挥弦、弹作怨歌。"]},{"t":"碧牡丹 自锡山却返武林，朋辈招邀，勉留十日，劳歌未已，重赋短章","f":"古风","c":["乍送轻帆去。","却趁回波住。","小别经旬，早是秋光催暮。","醉撷霜萸，怜断红非故。","伤心江上尊俎。","瘴乡路。","黯黯情味苦。","欢场可堪追溯。","怨绿眉峰，应念天涯风絮。","甚日重来，寻唾绒窗户。","一痕清泪弹处。"]},{"t":"应天长 章江雨泊","f":"古风","c":["绿波南浦离情赋。","争信生离情未苦。","玉飘烟，风泊絮。","才是世间肠断处。","粉笺书，罗袜步，目送武林人去。","消受鬓丝千缕。","短篷眠夜雨。"]},{"t":"解佩令 分宜中山矼戏作","f":"古风","c":["芦溪翘望。","萍乡翘望。","但宜春、已如天上。","陆地舟行，全不用、蒲帆兰桨。","尽船舷、石棱相抗。","林恋无恙。","书堂无恙。","累篙师、殷勤指向。","几首青词，便做得、丁家鹤相。","哂铃山、十年情况。"]},{"t":"喜迁莺 全州迤南古松夹道，连属百余里，苍云满天，元鹤欲下，此行为不负矣","f":"古风","c":["漓江行近。","讶凉伞万重，阴连无尽。","黛色浮空，樛枝拂地，幽赏驿程徐引。","悄然翠烟霏处，乍觉尘襟清润。","晚风峭，恍鸾吟吹下，瑶天笙韵。","曾问。","来雁否，衡岳片云，不许南飞趁。","何意征人，身轻一羽，却向玉簪留印。","望中五钗承盖，定有仙灵栖稳。","上元字，但眠蚕谁寄，悠悠芳讯。"]},{"t":"千秋岁引","f":"古风","c":["玉冷空枝，香残褪萼。","尺素缄情隔天角。","西楼未忘掩扇语，东郊枉负湔裙约。","画堂春，绿窗月，尽抛却。","依旧写愁银翰弱。","依旧忍寒罗衾薄。","锦瑟尘弦恨谁托。","青陵怨长纵化蝶，丹山梦远无归鹤。","任悠悠，小栏外，杨花落。"]},{"t":"更漏子 其一","f":"古风","c":["忆前欢，思往事。","一穗玉炉烟细。","罗幕下，绣帘垂，春寒能几时。","春欲暮。","愁仍住。","眼冷故乡何处。","凭梦去，寄书回，衡阳无雁来。"]},{"t":"更漏子 其二","f":"古风","c":["趁墟来，归峒去。","几阵绿榕丝雨。","敲社鼓，唱巫歌。","阴风生薜萝。","行不得。","炎方客。","江上越禽声急。","云惨淡，树模糊。","征帆天外孤。"]},{"t":"天仙子 其一","f":"古风","c":["屋角红蕉花未吐。","南风吹过飞鸾去。","桄榔阴里重行行，山枣路。","黄沙渡。","莫信泽家烟外语。"]},{"t":"天仙子 其二","f":"古风","c":["冻雨宵分声不定。","湘源涨起波千顷。","扁舟泛泛水中凫，斜又整。","乌竿影。","直过零陵人未醒。"]},{"t":"天仙子 其三","f":"古风","c":["一曲浯溪凉翠滴。","维舟更访前贤宅。","窊尊石镜尽留连，休去觅。","涪翁笔。","点点云根苍藓积。"]},{"t":"天仙子 其四","f":"古风","c":["前岁南行冬日好。","望衡九面清湘绕。","轻舟下濑又今年，烟浪渺。","麻阳小。","七十二峰如过鸟。"]},{"t":"天仙子 其五","f":"古风","c":["怪底朝来墙燕喜。","盈川相遇盈盈水。","一瓯茶罢便分携，情未已。","行还止。","终胜天涯书一纸。"]},{"t":"天仙子 其六","f":"古风","c":["渌口逆流流渐涩。","水车车水无涓滴。","一车才过一车来，沙岸逼。","风轮激。","跬步萍川天样隔。"]},{"t":"水调歌头 滕王阁","f":"古风","c":["彭蠡汇东泽，章贡绕西城。","江湖左右襟带，高阁峙崚嶒。","佩玉清歌散后，画栋朝云闻处，小队驻双旌。","帝子渺何许，长啸倚青冥。","神奇事，风借力，快扬舲。","绵津当日题字，墨彩尚飞腾。","不见才人江上，空有沙鸥别浦。","一舸待寻盟。","冷眼落霞外，天水碧无情。"]},{"t":"踏莎行 癸巳秋仲建昌县道中","f":"古风","c":["驿骑勤催，邮签缓递。","横波阻住青丝辔。","沙边唤得橛头船，劳人恰好闲身寄。","卧柳霜凋，野棠风细。","燕归无复营巢地。","伤心休问去年时，盈盈水是哀鸿泪。"]},{"t":"定风波 其一 潜山驿寄答佟艾生方伯","f":"古风","c":["飏鞭丝、几阵西风，人烟小市吹暝。","古驿延秋，虚堂款客，暂得羁魂定。","翠云深，玉沙净。","恰好灊庐秀眉映。","幽兴。","负松乔旧约，携琴萝径。","素襟漫整。","任缁尘、黯澹残痕凝。","向银笺，拂处寒香袖裛，岁晚心期订。","倚清吟，背窗影。","缥晕灯摇半花冷。","还省。","一声新雁、江南谁听。"]},{"t":"定风波 其二 宿州行馆再得艾生书却寄","f":"古风","c":["瘴云阴、卯饮杯停，骊歌柳岸催发。","冷落孤踪，凄迷影事，梦杳庄生蝶。","庾楼风，皖江楫。","带水盈盈限秦越。","情切。","到而今翻羡，羁禽天末。","翠笺半摺。","向邮亭、两度音徽接。","正相思，吟苦来鸿片羽，飘堕空廊叶。","妙香凝，古欢结。","洛诵兰言总心折。","行箧。","一编常对、澄怀秋月。"]},{"t":"琐窗寒 赋得依依墟里烟，途中书所见也","f":"古风","c":["澹拂楼阴，轻笼木末，暗催秋暮。","将开又合，只傍夕阳村墅。","任长空、片云自飞，等闲肯逐西风去。","向水亭山馆，千丝摇飏，为谁留住。","何处。","乡园路。","但断梗飘蓬，易牵离绪。","年光过眼，消得几番炊黍。","赋郊居、尘鞅未闲，耦耕旧约人在否。","忍相看、数点霜枫，冷红鸦外舞。"]},{"t":"满江红 其一 重过粉坊琉璃街故居","f":"古风","c":["屋角高槐，闲问讯、宣南坊陌。","记此地、琴尊跌宕，几年栖息。","半剌相忘磨灭后，一家正好团栾日。","任旁人、错比子云居，喧尘隔。","离聚苦，无终极。","生死恨，难抛掷。","但天台重到，凄凉岑寂。","芳草廊空蝴蝶化，茜纱窗冷蟏蛸织。","叹乌衣、巷口燕归来，今成客。"]},{"t":"满江红 其二 都中戏答人问","f":"古风","c":["万古云霄，问一羽、何人当得。","但随分、南州承乏，油幢画戟。","假节文从炎汉仿，借绯句亦香山觅。","尽翩翩、斜压帽檐攲，螭坳立。","曾待漏，金门夕。","曾视草，銮坡侧。","却翻疑定远，功成投笔。","麋鹿方惭簪绂系，貂婵那自兜鍪出。","是虎贲、还是蔡中郎，君须识。"]},{"t":"满江红 其三","f":"古风","c":["小别庐山，惜真面、忘携粉本。","费半日、东涂西抹，徒供一哂。","有客同来吴季子，平生最识周公瑾。","尽从旁、指示颊三毫，心难印。","嘶骑发，装池进。","踪迹远，须眉近。","怕丹青见惯，因疑成信。","他日重飞天上写，诸君但索图中骏。","却翻猜、扇外放翁谁，惊相问。"]},{"t":"满江红 其四 过新城县，买得白梁米，忆亡友李宾（宾石新城人）石孝廉同寓地藏庵旧事感赋","f":"古风","c":["一磬僧房，记月下、人来款竹。","还远致、秋塍珠宝，累累盈斛。","红豆分拈花里句，胡麻共饱山中粥。","更无须、乞米似平原，书成幅。","蒿里唱，当年曲。","萍梗系，谁家屋。","望子猷门径，凄凉心目。","过眼云烟朋辈少，打头风雪官程促。","问劳劳、尘梦定何时，黄梁熟。"]},{"t":"满江红 其五 途中与客说家乡肉","f":"古风","c":["旅食匆匆，话前事、齿芬犹结。","忘不了、衙斋近局，消寒时节。","馈岁相携春酿早，佐餐雅称冬春洁。","未输他、松火玉织薰，桐严楫。","吾旧里，樊江涉，今小筑，夷门接。","甚杭州风味，尊前贪说。","三载身惭东道主，片帆梦冷西湖月。","但溪山、好处即家乡，休分别。"]},{"t":"感皇恩 王庄阻雪二阕 其一","f":"古风","c":["滕六太颠狂，搓绵搅絮。","币月霏霏困归羽。","泥深没踝，已是津梁迷误。","候人还为说，冰横路。","茅屋短垣，荒村且住。","泼水衾裯酽寒护。","瞢腾一枕，只见玉龙飞舞。","断魂寻不到，章门渡。"]},{"t":"感皇恩 王庄阻雪二阕 其二","f":"古风","c":["留滞意如何，天公休问。","惯遣飞霙上愁鬓。","望云心事，争得落霞红趁。","远游应为我，萦方寸。","玉戏未闲，珠杓空迅。","饯腊杯传岁将尽。","鱼沈雁杳，料是清寒难忍。","旅窗谁与递，春来信。"]},{"t":"珠帘卷","f":"古风","c":["东堂畔，晓风吹。","轻燕澹粉迷离。","垂柳摇摇无绪，闲扶墙外枝。","远路春光晼晚，残宵梦语依稀。","争唱渡头桃叶，浑不解，寄相思。"]},{"t":"汉宫春 药洲访石图，为翁二铭学使题","f":"古风","c":["花药澄湖，乍英光旧迹，辉映庭隅。","天教化工在手，璧合星枢。","莲亭志喜，胜苏斋、残拓临摹。","凭证取、题名掌上，当年陈九仙书。","邂逅章门持节，几留宾下榻，访古停舆。","新携换鹅妙墨，一笑披图。","山阴茧纸，比炎洲、片石何如。","羡使者、怜才似此，人间谁叹遗珠。"]},{"t":"绛都春 拟吴梦窗","f":"古风","c":["鸳针绣倦。","又珊枕梦回，青禽低唤。","唤起絮云，咫尺天涯愁无限。","回廊步屧成新怨。","况别母、啼妆犹恋。","断肠空指，灵芸帕上，泪痕红泣。","凝眄。","盈盈带水，片帆趁、燕影风柔波软。","佩解汉皋，那信花开归来缓。","圆冰写翠秋容换。","认娥月、西窗人面。","紫箫吹入吴歈，桂香夜暖。"]},{"t":"喜迁莺 其一 红梅","f":"古风","c":["罗浮仙侣，也闲趁好春，脂痕匀注。","艳魄还丹，冰肌晕酒，依约绛唇初吐。","翠禽为谁啼醒，却向朱门留住。","问名字，记吹箫低唱，松陵前度。","偷觑。","窗外影，嵰雪万重，梦冷来时路。","倚竹新妆，巡檐浅笑，不管缟衣人妒。","十分出尘香韵，一例凡花输与。","拟标格，算人间只有，秦郎词句。"]},{"t":"喜迁莺 其二 同人小集螺墩，花事已过矣，赋此以续李重光恨来迟曲","f":"古风","c":["晴烟吹絮，对嘉树秀筠，栏干闲拊。","屐齿香痕，裙腰草色，多事晓莺争诉。","好花倩魂空往，佳约芳期终阻。","凤弦曲，但临觞休按，红盐新谱。","南浦。","离恨远，清浅半湾，不是仙源路。","流水三生，碧云千里，锦字懒传幽素。","黯然一江风浪，归棹还催人去。","楚天暝，想轻寒已到，驯鸥眠处。"]},{"t":"喜迁莺 其三 红袖添香夜读图，为王蓉洲孝廉题蓉洲余僚婿，今皆作玉溪生久矣","f":"古风","c":["兰釭红绽。","更偎倚画中，春风人面。","钗影横窗，书声出屋，恰和小莺低啭。","篆纹蕙炉轻袅，冶思梨云相乱。","可人语，问芸编何似，柔乡堪恋。","眉案。","还记取，箫凤谢庭，一例神仙眷。","好梦难留，潸痕宛在，憔悴玉京重见。","绛河旧情空溯，珠树才名争羡。","称心事，待浓薰秘省，宫袍催换。"]},{"t":"喜迁莺 其四 陶凫芗同年为觅教场胡同宅丁香二株可爱，急欲移居而不得，赋此解嘲","f":"古风","c":["频番胥宇。","似春燕乍来，偷窥帘户。","萍梗孤踪，兰言一诺，刚被玳梁留住。","广庭十弓犹欠，琼萼双身先睹。","胜情引，小书堂怡在，花阴深处。","空误。","前度客，三匝故枝，欲去仍回顾。","事逐烟凉，人如舟系，偏托石尤风阻。","几时素尘闲扫，著我琴尊容与。","粉香里，试清吟好约，柴桑仙侣。"]},{"t":"喜迁莺 其五 三官廊海棠，高花簇锦，阴如槐幄，或言是当阳董文恭师手植","f":"古风","c":["春情寥寞。","又缓款信风，吹开仙萼。","柳外鞭摇，城隅路转，闲赴紫绵芳约。","宿酲太真初醒，悄倚瑶台珠箔。","泥人处，弄娇姿还胜，翻阶红药。","犀杓。","休更举，重溯梦华，酒味浑忘却。","一日欢游，百年遗恨，谁会此时哀乐。","旧山富春空冷，馀荫香林犹托。","便归好，怕西州清泪，弹将花落。"]},{"t":"浣溪沙 乙未冬偶过北兰寺","f":"七言古诗","c":["旧隐西陂迹已陈。","尚留诗屋寄云门。","梵钟声里几晨昏。","物外山含无尽意，定中僧笑傥来人。","烟波何处问迷津。"]},{"t":"鹧鸪天 其一","f":"古风","c":["腊雪春霖报岁丰。","等闲欢意少人同。","湘帘燕子双双剪，别院桃花阵阵风。","浮凿落，唱玲珑。","临歧不惜醉颜红。","抟沙聚散寻常事，只当相逢是梦中。"]},{"t":"鹧鸪天 其二","f":"古风","c":["江国阴阴水拍堤。","五年三见泽鸿飞。","可堪社鼓嬉春日，却是征衫上路时。","人不见，梦还疑。","此情争得片云知。","从容坐啸吾何敢，看取吴霜鬓几丝。"]},{"t":"鹧鸪天 其三 琵琶亭","f":"古风","c":["一曲琵琶洒半酣。","当时何苦泪痕淹。","生来泛梗原无著，听彻哀丝亦未嫌。","人欲去，句重拈。","清词闲写望江南。","怜他老大商人妇，只唱新声昔昔盐。"]},{"t":"鹧鸪天 其四","f":"古风","c":["惭愧云亭半载留。","又衔恩命向炎州。","遄征有幸骑宫马，乐事无因恋爽鸠。","寻故步，话离愁。","觚棱天半梦悠悠。","十年前后三持节，蒿蔚馀生已白头。"]},{"t":"谒金门 其一 未至枫香十馀里山水，骤发借宿村舍","f":"古风","c":["行不得。","何处箜篌唤客。","坼岸崩沙天易黑。","荒村聊寄迹。","此际兰釭频剔。","梦里关山闲觅。","瓮牖绳枢环堵室。","凤楼人未识。"]},{"t":"谒金门 其二","f":"古风","c":["愁脉脉。","还是飘蓬踪迹。","水远山长音信隔。","秋衾残梦积。","燕子欲飞无力。","何处人家坊陌。","如此光阴如此客。","相思留不得。"]},{"t":"惜分飞","f":"古风","c":["烟外游丝风里絮。","几日分飞又聚。","西笑长安路，故人杳隔云深处。","乐事潘舆天付与。","还向枫香唤渡。","今夜舒城住。","梦魂已过江南去。"]},{"t":"大酺 舆行蕲黄山中，纡回深秀，大似蜀道风景，江楚少陆行者，特为拈此","f":"古风","c":["又玉沙清，瑶林映佳景，欣逢山驿。","行行青不断，讶修眉天际，黛痕如拭。","栈阁曾经，巫峰恍遇，应有幽禽相识。","萍踪依然在，但愁拈客鬓，岁华非昔。","况吟屐重寻，宋贤芳躅倍添凄恻。","鸡鸣还暗惜。","最惆怅、烟缕词人笔。","尽殿上、新歌传唱，谏疏长留，总销沉、茂陵宣室。","异代襟情，"]},{"t":"留客住","f":"古风","c":["东风菜，叹多时、抛残乡味，枉了隋堤春色，绣畦相待。","欲问樊楼浅酌，旧梦何处，剩有承筐新翠，压担馀寒，相思市桥吟卖。","赏心再。","负绮语潘郎，春明词债。","纤手青丝，莫任年华催改。","此际晶盐一箸，赋才无碍。","句好应寄南雁影，指莺脰、水边按谱人在。"]},{"t":"桂枝香 署中丛桂数十株，交柯接荫，百年物也。今秋著花尤盛，词以赏之","f":"古风","c":["虚廊纵目，又露湿晚秋，庭院如沐。","还见云根秀倚，雾绡凝绿。","西风不管青腰守，任吹开、万枝金粟。","客衣尘冷，依稀犹染，小山馀馥。","念傅舍、光阴转毂。","尚吟玩珠英，情寄三宿。","一例茵凭，自许赏心人独。","天香正好披襟处，更佳音仙蕊初擢。","故国此际，霓裳应听，广寒新曲。"]},{"t":"洞仙歌 李石梧观察以梧笙馆联吟图卷索题，小病久置案头，及石梧悼亡始成此阕","f":"古风","c":["春风梧苑，惯柔毫闲弄。","况有兰闺玉人共。","向金台、斗韵珠海分笺，全不数，当日秦娥箫凤。","梁园飞絮早，绿绣空囊，岂意韶华遽相送。","银字掩孤嚬、一卷哀辞，叹我已、潘丝霜重。","算香散、蘅芜十年馀，又振触、西湖那时残梦。"]},{"t":"南乡子","f":"古风","c":["孤影又南翔。","岁晏何心问稻粱。","卵色天低秋水阔，茫茫。","忍说他乡胜故乡。","灯火记书窗。","锦样修翎正著行。","三十五年才一梦，凄凉。","却向襄阳话洛阳。"]},{"t":"朝中措 自题山水小景","f":"古风","c":["吴绡尺幅写幽襟。","寸碧倚瑶岑。","地僻更无人问，山虚不在云深。","圆波澄镜，方流折玉，佳趣堪寻。","一穗白苹烟影，等闲凉到秋心。"]},{"t":"齐天乐 其一 过金梁桥","f":"古风","c":["十年一觉春明梦，鱼梁尚留残照。","片月牵魂，新词按谱，为尔羁怀萦绕。","尘襟净扫。","尽曲记流珠，句拈香草。","倦枕低回，旅窗红晕一灯小。","荒湾依旧断板，素蟾凉影外，幽境重到。","岸柳轻阴，烟莎澹碧。","几日西风吹老。","归来自好。","只袖底银笺，赏音人少。","付与清吟，晚蝉秋树杪。"]},{"t":"齐天乐 其二","f":"古风","c":["武昌官柳依依处，诗翁旧游曾说。","啸侣身闲，哦秋句好，未信风流消歇。","桐阴翠叠。","为重续前盟，乍添新叶。","扇底清芬，赋情应许汉皋接。","香名传遍画省，况金昆墨妙，吟社同结。","事往题襟，人来落帽。","肯负萸红时节。","披图意惬。","见一角螺云，半湾芦雪。","又触相思，剡溪今夜月。"]},{"t":"齐天乐 其三 樱桃，和张诗舲方伯","f":"古风","c":["珍丛分得安陵种，垂檐几丝风袅。","翠褓悬馀，筠笼赠处，量取圆珠多少。","羁魂暗绕。","问寒食东田，甚时重到。","此日尝新，转蓬空自系愁抱。","柴车双洎路引，指繁星密缀，千树红小。","荐笋光阴，秉蕳节物。","长忆家园春好。","韶华误了，但锦字书沉，玉簪人老。","梦里松楸，近年谁为扫。"]},{"t":"好事近 其一","f":"古风","c":["冷落七陵烟，秋在玉津园侧。","三载金梁月底，住天涯羁客。","侯家冈树望中迷，来去总衔恤。","忍说潇潇风雨，作他乡寒食。"]},{"t":"好事近 其二","f":"古风","c":["招隐故人书，孤负锦笺盈箧。","拈出中仙词句，但拥门黄叶。","玉觞无味已多时，怀抱向谁说。","惆怅燕莺声里，赋晓风残月。"]},{"t":"好事近 其三","f":"古风","c":["一棹柳园津，还拟汴堤游历。","珍重陌头烟缕，付登楼人忆。","秋花驿路尚多情，尘外似相识。","错向凄红冷蕊，认春风颜色。"]},{"t":"巫山一段云 庚子秋仲廪延道中","f":"古风","c":["野色侵衣袂，秋痕恼鬓丝。","碧云无尽鸟飞迟。","心事定谁知。","忆别空馀梦，言归未有期。","斜阳冉冉柳依依。","长记出门时。"]},{"t":"汉宫春 其一 汤阴岳鄂王祠","f":"古风","c":["已矣金牌，叹黄龙痛饮，此志终乖。","谁令雨河尽弃，并弃江淮。","机危祸惨，问苍苍、何意生才。","空恸惜、风波狱底，英魂毅魄长埋。","当日精忠赐字，幸小朝气振，康构心开。","长驱背峞劲旅，敌焰应摧。","权奸卖国，任中原、板荡兴哀。","侥幸煞、强邻酌酒，免教胆落飞来。"]},{"t":"汉宫春 其二 邺下","f":"古风","c":["漳水名都，被浊流淘尽，霸业当涂。","铜台那时片瓦，一例榛芜。","苴茅建国，逞雄心、炎运将徂。","浑未省、当歌对酒，人生朝露无殊。","还是闺房眷恋，笑分香卖履，遗令区区。","知他画眉未毕，鬼妾谁娱。","残魂馁矣，更何人、上食朝晡。","君不见、西陵废垄，年年衰柳啼乌。"]},{"t":"剔银灯 磁州数十里间，清流夹道，蒲稻弥望，北辕所仅见也","f":"古风","c":["一路缁尘恼客。","恰有磁州今日。","滑笏圆波，回环浅渌，仿佛旧游曾历。","劳劳行役。","只此处、烦襟消得。","芳草谁家兰泽。","想像渔庄鸥国。","柳影缘堤，菰香吹水，点出倪迂小笔。","轻舟倘觅，胜吟倚、一鞭秋色。"]},{"t":"氐州第一 泥涂困惫，道旁金山寺僧庐甚洁，因就宿焉。寺在赵州南二十里","f":"古风","c":["斜日山衔，高岸路阻，愁看涨潦千顷。","暮色冥迷，修途困顿，争得羸骖再整。","弹指青莲，乍现出、招提幽境。","远客心孤，虚寮夜寂，妙香凄冷。","对语枯禅浑未省。","梵吟外、自寻清咏。","细字银笺，秋灯剪处，说倦游萍梗。","卷罗云、窗送晓，沾泥絮、依然不定。","壁上重题，任长留、空花小影。"]},{"t":"天香","f":"古风","c":["衰柳攲烟，虚堂面郭，微波照影清泚。","路隔平沙，门横浅渌，大好寄鸥闲地。","参差雉堞，送暝色、凉生襟袂。","只少西山拄笏，分他绛霄云气。","餐霞胜游漫拟。","但招携、玉珂兰契。","一榻六街尘外，簟纹如水。","商略庭阴半亩，要秀竹、疏槐翠相倚。","待约明年，春禽唤起。"]},{"t":"扫花游 铁仁山总宪招游城西某氏园","f":"古风","c":["粉垣带郭，是旧日朱门，赏心佳处。","翠笺唤侣。","借闲园半角，胜游星聚。","倦客幽寻，过眼韶华试数。","悄回顾。","问选石莳花，人更何许。","兰锜今在否。","但艳槿沤珠，暗随春去。","燕归自语。","叹高楼似昔，杏梁谁主。","卧柳攲桥，总被群鸥占取。","小山句。","为王孙、桂丛吟苦。"]},{"t":"庆清朝 晚登陶然亭寄怀衎石汴中","f":"古风","c":["野水弯环，空烟澹薄，孤亭尚恋斜晖。","游骢散后，幽寻尘外偏宜。","暗想南湖雁影，翩然冲雪独吟时。","萧闲境，冷怀高韵，襟抱谁知。","今我瘦藤倦倚，对女墙西畔，隐约山眉。","虚廊坠叶，从前爪印都迷。","换尽芦湾细柳，一枝不借暝鸦栖。","夷门路，闷拈新句，遥寄相思。"]},{"t":"望海潮 京寓对雪","f":"古风","c":["重阴垂幕，长空卷絮，纷铺万顷琼田。","鱼梦乍古，鲸波未息，南云尚驻戎旃。","风劲铁衣单。","想营屯千帐，清角吹寒。","胜事园林，漫将尊酒赋华筵。","家家腊鼓腾欢。","待功成洗甲，庆入新年。","银海浪平，天花阵舞，从教净扫蛮烟。","一白虎门山。","看欃枪夜落，旌旆春闲。","料得红旗送喜，早晚到长安。"]},{"t":"探春慢 辛丑都门元夕二首 其一","f":"古风","c":["紫陌春回，禁城夜暖，琼箫灯市吹起。","漠漠烟痕，溶溶月色，掩映曲坊珠翠。","嗟念文园老，渐羞趁、落梅秾李。","玉荷滴尽兰膏，不堪纤梗犹系。","重溯槐街旧侣，曾几度擘笺，同赋蓝尾。","二十年来，游仙一枕，消得光阴弹指。","亲友凋零甚，更休问、贞元朝士。","笑语谁家，听残莲漏声里。"]},{"t":"探春慢 辛丑都门元夕二首 其二","f":"古风","c":["彩笔愁拈，画屏倦倚，良辰谁共游冶。","小篆香消，微波帘卷，还又夕阳西下。","曾说金钱买，信一刻、春宵无价。","旧时月色依然，酒边心事慵写。","此际乡城漏永，应扫尽碧云，庭院潇洒。","暗卜油花，频挑烟蕊，遥忆长安今夜。","相对团栾影，尽肠断、吴兰词帕。","梦约教寻，从他灯穗红灺。"]},{"t":"惜秋华 其一 偕许滇生、少农、斌梅舫同聊，宿万寿寺","f":"古风","c":["秀挹庭阴，破烟霏、放出林间山影。","茶话未阑，侵寻竹房催暝。","相携半榻闲身，到世外、栖鸦才定。","清听。","又廊腰、暗落风边凉磬。","前事枉重省。","叹衣珠无觅，鬓丝尘凝。","新侣旧、欢依然，素心堪证。","看花待约芳期，问何日、翠娇红靓。","松径。","且明朝、玉栏同凭。"]},{"t":"惜秋华 其二 媭砧课读图为王少鹤农部题","f":"古风","c":["旧业青箱，诵先芬、幸托茕茕月姊。","珠树俊才，名成捣衣声里。","冰绡细写前尘，照灯影、柴门深闭。","谁记。","有元龙、省识当时情事。","宫锦艳柯里。","是寒砧叠就，香罗文绮。","霜杵泪、痕悽红，尚沾掺指。","扁舟画省归来，胜清沔、相望天际。","迎侍。","趁明年、一帆春水。"]},{"t":"燕归梁 汲县与家人别","f":"古风","c":["烟柳凄迷夕照沈。","离思难禁。","无根风絮苦商参。","歧路外、两分心。","促春相见残春别，新怅望、更从今。","竹鸡啼处瘴云深。","且休向、梦中寻。"]},{"t":"宴清都 其一 从弟耕腴俟我于管城，同行至许昌辞归里门，怃然有作","f":"古风","c":["翠羽东风便。","邮程隔，始知家近天远。","看云念久，连床梦熟，快心重见。","题襟怕说分襟，况旧隐、仍孤望眼。","试问取、老圃闲花，横枝暗叶谁剪。","匆匆半载京华，尘劳自省，羁思空乱。","繁台夜月，隋堤细柳，一番春换。","相携步屧吟眺，胜路逐、衡湘去雁。","待长成、新种丹榴，归来未晚。"]},{"t":"宴清都 其二","f":"古风","c":["候馆騑骖驻。","苔岑合、夜阑前事重数。","晨星半落，闲云独往，乍欣萍聚。","长安片月回看，奈过眼、徒惊迅羽。","枉羡忆、紫陌吟身，年华驷隙空度。","南来第一消魂，凄凉况指，江上鹦鹉。","春晖寸草，秋风断梗，此情谁语。","陵陬绛萼馀恨，更忍问、循陔旧处。","但与君、剪烛同听，西窗暗雨。"]},{"t":"倦寻芳 其一 渡汨罗","f":"古风","c":["素波箭激，新涨奁平，舟舣烟浦。","道左残碑，题字不堪重抚。","寂寂江天如梦寐，悠悠湘水无今古。","悼贞魂，但怀沙事往，九歌悽苦。","忆泽畔、行吟憔悴，渔父难招，詹尹空诉。","怨偶椒兰，争念美人迟暮。","鱼腹长怜埋恨日，蛾眉岂有容身处。","近端阳，听迎神、数声箫鼓。"]},{"t":"倦寻芳(衡阳阻雪) 其二","f":"古风","c":["佩兰怨曲，啼竹潸痕，魂断何许。","吊古人来，还是冻云愁聚。","倦雁稀迎前度客，昏鸦冷寄谁家树。","数归程，但梨花梦隔，扣舷空阻。","念几日、湘南留滞，窗暝栖烟，灯暗吹絮。","望眼冥迷，不到夕阳红处。","拂槛徒夸群玉见，推篷忍看飞琼舞。","倚新词，待催将、棹歌声去。"]},{"t":"阮郎归 余以嘉庆癸亥就婚于长沙郡署，阅今三十九年，旧游重历，距先室之殁一星终矣","f":"古风","c":["片帆当日溯湘波。","春光媚绮罗。","一鞭今日再经过。","骚辞怨女萝。","云黯澹，路盘陀。","行行山更多。","鹧鸪声入越巫歌。","征人可奈何。"]},{"t":"澡兰香 长沙重午用梦窗韵","f":"古风","c":["秦萧旧侣，楚佩馀情，一枕蕣华梦觉。","前踪好在，令节依然，枉说茜窗人约。","袅钗符、续命无凭，魂消幽兰半萼。","采艾吟心，怨入离披汀蒻。","想像庭扉掩处，泪点湘筠，尚栖仙魄。","花源棹舣，橘社书传，忍问坠蛛尘幕。","尽相看、露井银瓶，谁摘梅黄劝酌。","步倩影、月夜归来，三芝栏角。"]},{"t":"念奴娇","f":"古风","c":["五湖空约，为迷津、翻学鸱夷生计。","钓艇渔舟频唤取，替却駪駪征骑。","蕙带徐搴，荪桡缓荡，万顷玻璃碎。","青溪几折，晚风吹梦无际。","当日跨凤偕归，玉尊双饮，笑语篷窗倚。","一绿鸳波依旧好，谁念羁禽身世。","帝子贞筠，灵均香草，况是埋忧地。","楚骚歌罢，水天何限愁思。"]},{"t":"踏莎行 风劲小舟可危，倩乡民道行山中三十馀里，暮宿衡岳道院","f":"古风","c":["路阻横波，人来仙馆。","迷途巧借东风便。","当时九面望湘帆，谁知灵境寻常见。","楚竹烟迷，越禽声唤。","榕湖计日征尘浣。","旧游风景记分明，无因说与衡阳雁。"]},{"t":"醉蓬莱 全州古松余尝有词纪之，十年再至，存者无几，俯仰今昔，殆难为怀","f":"古风","c":["又衡云过尽，咫尺湘源，旧游重到。","望里平林，怪翠烟如扫。","凤叶凋香，虬枝剪玉，任摧残多少。","一曲薰风，等闲翻入，怨琴凄调。","金谷杯传，绣笺吟倚，帐烛檐花，只供清啸。","大好灵踪，付乱鸦残照。","物自无言，树犹如此，更何人不老。","两度骖鸾，千年归鹤，梦回空恼。"]},{"t":"浪淘沙 题黄杏帘广文《漓江归棹图》，即送还里","f":"古风","c":["一棹许湾春。","旧里情亲。","金萱花下彩衣新。","空阻陡门三十六，无计留宾。","蕙帐隔吟身。","鹤怨频闻。","北山原有去来云。","明日片帆江汉上，我亦归人。"]},{"t":"酒泉子 其一","f":"古风","c":["染黛天低。","摇飏东风云一缕。","乍疑晴，还欲雨。","两迷离。","麝薰消尽罗衾薄。","凉意袭人人未觉。","紫徘徊，红踯躅。","唤春归。"]},{"t":"酒泉子 其二","f":"古风","c":["往事寻思。","倦枕闲偎屏半掩。","月明残，灯烬暗。","晓星移。","采香惯向幽丛趁。","怨粉愁红谁与问。","蝶无情，花有恨。","各分飞。"]},{"t":"酒泉子 其三","f":"古风","c":["绿暗红稀。","昨日东风今日客。","绣奁空，珠履隔。","昔游非。","曲房幽径无人处。","却是闲花偏解语。","白云编，黄石墓。","有谁知。"]},{"t":"庆春时","f":"古风","c":["早春帘户，良宵风月，懒近芳卮。","凝珠蜡凤，衔花彩燕，长忆少年时。","寒梅香信，窗外幽梦谁知。","苔笺自倚，兰釭频剔，留待晓鸦啼。"]},{"t":"江城子","f":"古风","c":["岭南西路梦悠悠。","听蛮讴。","叫钩辀。","长向剌桐、花底赋离忧。","勾漏丹砂无觅处，春易尽，水空流。","几回丹旐送归舟。","忆同游。","影仍留。","一线斜阳、犹恋竹棚头。","老去文渊重曳足，南雁外，怕登楼。"]},{"t":"渔家傲 末疾艰于步履疏开，缺交篆后，书寄汝筠，时在丙午七月","f":"古风","c":["六十五年嗟老矣。","衰残那更朝衫系。","人说归来陶令拟。","知也未。","乡园风景而今异。","浩劫连番瓜蔓水。","嗷鸿中泽馀生寄。","寒故凄凉书一纸。","蓬户底。","相看可有相怜计。"]},{"t":"摸鱼儿 其一 索陈桂舫孝廉写村居图扇","f":"古风","c":["古咸平、数椽小筑，乡村风物堪溯。","柳堤槐巷寻常景，幽意也传毫素。","君傥许。","为点染、来青粉本瓯香谱。","闲云貌取。","更六枳篱边，邻翁三雨，倚杖话农圃。","郊居好，消受竹晨花午。","漫嫌归计迟暮。","沉吟后约从君问，画里可能同住。","清汴路。","梦不到、绿榕红豆衔杯处。","低回俊侣。","对几摺疏筠，相思未抵，官阁剪灯语。"]},{"t":"摸鱼儿 其二 发桂林日再赠桂舫，时与之同舟而北","f":"古风","c":["散蜂衙、著春无处，寥寥尘梦今醒。","青罗碧玉依然好，簪组那容衰病。","迟暮景。","空愧负、嘤呜丽句纷投赠。","鸥盟未冷。","待扫尽烦襟，携将胜友，敧枕棹歌听。","残冬日，漫说沧波路永。","岁寒心事堪证。","湘兰楚竹遥相待，只要一帆风正。","还自省。","怕汉渚，隋堤容易分萍梗。","停骖傥肯。","为点笔重描，金梁月底，新柳几丝影。"]},{"t":"玲珑四犯","f":"古风","c":["欲霁仍迟，蘸淡墨云痕，低护轻霭。","湿粉疏窗，恰是碎琼堪爱。","休笑冻粟皴肌，尽梦倚、玉林瑶界。","伴冷吟姑射仙影，多幸短篷同载。","贾生祠畔曾游处。","想探芳、庆湖人在。","早梅暗逗春消息，容易风光改。","争奈怨入素琴，还泪洒、幽兰弦外。","叹软红尘里，茶香酒绿，此情难再。"]},{"t":"望湘人 丙午除夕，泊舟洞庭湖鹿角，书所见","f":"古风","c":["又嬉春画鼓，迎岁绣幡，半湖灯舫相倚。","响竹惊鸦，素波泛蚁。","草草辛盘风味。","六博酣歌，判教忘了，征途憔悴。","任远空、一抹烟痕，冷却君山眉翠。","乘兴船窗更启。","待桃符句索，彩毫闲试。","奈天角孤云，尚隔故园千里。","吟香旧、馆玉笺谁寄。","几日新韶弹指。","嘱好梦、今夜先归，看取梅花开未。"]},{"t":"长相思 岳州元日","f":"古风","c":["双桨催程，半帆借泊，危楼高倚层云。","风光自好，暮景仍斜，禁他箫鼓千门。","窗隙流尘。","但屠苏送老，醽醁悽魂。","波泛碧鳞鳞。","有天涯、诗句怀人。","念珠络藏香，绣檀携枕，归舟曾系兰津。","昙花空外影，总飘然、残梦无痕。","欲话前因。","应恨敛、湘娥翠颦。","掩孤篷，休教字写宜春。"]},{"t":"西子妆慢","f":"古风","c":["帆角低垂，船舷侧转，借得横斜风势。","画桡容易送轻航，问终朝、乱流何意。","骑危漫拟。","称倦客、闲眠偎被。","荡吟魂，笑雨云翻覆，浮生如寄。","人间世。","行止由天，斗捷非吾事。","巧心妍手任营营，但忘机、狎鸥久矣。","乌竿志喜。","看綄羽、飘摇北指。","劝长年，好去摊钱浪里。"]},{"t":"蓦山溪 汉口三宿，灯市喧闻，殊有春意","f":"古风","c":["晴川黄鹤，与我周旋久。","天外一帆风，破馀寒、轻装来又。","箫声吹暖，刚是上元时，青嶂月，锦街灯，夜色明于昼。","刘郎重到，往事休回首。","冷落旧巢痕，想依然、燕支红透。","桃花开早，何处媚芳春，迎过舫、送归鞍，不及长亭柳。"]},{"t":"最高楼","f":"古风","c":["黄尘里，村墅半榛芜。","且幸见吾庐。","春风拂面馀寒在，晨星偻指故交疏。","问家中，猿与鹤，近何如。","也不为、柴桑三径菊。","也不为、淇园千亩竹。","衰病体、愧簪裾。","坐忘只合匡床倚，行吟仍怯短筇扶。","且安心，重补读，少时书。"]},{"t":"四字令","f":"古风","c":["吟香绮栊。","传诗翠筒。","玉梅才识春容。","酿春光未浓。","虹梁半空。","鱼波万重。","旧时月色相逢。","话家山梦中。"]},{"t":"阮郎归","f":"古风","c":["昨宵同赋冶春词。","芳襟暗共期。","今朝却是送春时。","红螺懒更持。","来又恨，去还思。","凄凉花一枝。","哀筝弹损远山眉，此情金雁知。"]},{"t":"阮郎归","f":"古风","c":["朝来春色媚檐牙。","晴晖散曙霞。","晚来秋影到窗纱。","新眉试月华。","罗帐倚，绣帘斜。","催归梦未差。","红灯开作可怜花。","今宵真到家。"]},{"t":"青玉案","f":"古风","c":["西山颜色仍依旧。","只添了、眉痕皱。","小院珠帘垂永昼。","吟笺半摺，画栏孤倚，长忆分襟后。","闲中记曲拈红豆。","风雨还惊夜来骤。","曾问南园芳事否。","莺如人懒，花如人醉，春也如人瘦。"]},{"t":"一剪梅 春水和李宾石","f":"古风","c":["一镜烟痕望里收。","咫尺回桥，绿软香柔。","有人扶上木兰舟。","载了春心，荡了春愁。","冶叶传情恨未休。","照影婵娟，那处妆楼。","小红栏外是西洲，今日东风，明日东流。"]},{"t":"蝶恋花","f":"古风","c":["门外垂杨千万缕。","不系春光，只系春愁住。","文杏巢空双燕去。","紫箫声里屏山暮。","恨别江郎浑懒赋。","一抹烟痕，旧约无寻处。","五里东风三里雨。","蘼芜吹冷天涯路。"]},{"t":"蝶恋花 送芙初南归二解 其一","f":"古风","c":["帘底斜阳红一线。","怕近黄昏，不放银钓卷。","烛影西堂看又短。","金尊只讶宵来浅。","赋罢离情魂欲断。","砧杵谁家，唤起征人怨。","冷到秋心秋不管。","芙蓉却在江南岸。"]},{"t":"蝶恋花 送芙初南归二解 其二","f":"古风","c":["往日题襟同客邸。","一树垂杨，两两吟匏寄。","小巷城南三五里。","等闲化作盈盈水。","天上秋云吹易碎。","送得君归，却问归何计。","燕子楼台斜日里。","江南也是消魂地。"]},{"t":"瑞鹤仙","f":"古风","c":["素天分雁轸。","话梦影扬州，月痕初晕。","情波寄兰讯。","又鱼笺唾湿，麝煤心印。","琴歌兴引。","且漫说、游踪未准。","但匆匆、侧帽吟来，输与旧时青鬓。","还问。","双藤在否，络架扶墙，几番红褪。","交枝翠隐。","苍藓路，有谁认。","怕幽禽忘了，花魂清瘦，却道栖香正稳。","倚黄昏、栏角尖风，峭寒自忍。"]},{"t":"一枝春 白芍药","f":"古风","c":["婪尾杯深，殿群芳付与，伶俜花影。","娇姿澹扫，不许绮罗人并。","蔷薇卧晚，记曾共、曲栏闲凭。","空自把、情泪偷含，梦入琐窗烟冷。","湔群素波低映。","渐韶华过却，将离折赠。","东风倦眼，到得粉融酥凝。","浓春未了，问谁见、玉奴妆靓。","还更怕、残月扬州，杜鹃唤醒。"]},{"t":"西湖月 题孤山放鹤图","f":"古风","c":["巢居不锁仙心，弄远影褊褼，绛霄风稳。","素裳缟袂，澄湖十里，翠峰千仞。","圆吭清响递，更两两、瑶笙松吹引。","尽恋著、岭畔梅花，肯说玉京飞近。","软红我尚淹留，叹蕙帐尘空，怨怀谁讯。","故园秋矣，缡褷瘦翮，不堪重认。","芝田归有路，但倦羽、商量期未准。","枉回首、梦里青山，白云无尽。"]},{"t":"陌上花 七夕","f":"古风","c":["双星寄语红罗，亭上旧香谁采。","丽句南唐，吹冷半空仙籁。","当时恨与东流去，容易朱颜催改。","庆长生、唱出凤箫一曲，闷持罗带。","话前因、梦里填桥乌鹊，那见纤云飞盖。","片石支机，还是聘钱难贷。","占丝钿合空相约，孤负西楼人待。","但清秋、认取梧桐深院，赋情犹在。"]},{"t":"念奴娇","f":"古风","c":["翠奁亭畔，话西风、一笛清游曾记。","已是离愁消未尽，禁得危栏重倚。","别浦凝阴，回塘弄晚，摇漾沧洲意。","前番衰柳，向人还又憔悴。","长恨千里关山，南云不见，见苍烟无际。","帽影缁尘江上路，多分霜丝难理。","潮落秋生，水凉梦远，休唤眠鸥起。","相思何许，白萍红蓼乡里。"]},{"t":"解连环 雪意","f":"古风","c":["画檐岑寂。","送寥空倦眼，乱鸦飞急。","护冻云、戏玉犹悭，任剪取凤翎，不成抛掷。","睡起痴龙，但小试、残年风色。","照银灯点点，絮粉泪痕，何处相识。","幽寻灞桥路隔。","对薰炉篆缕，清梦难觅。","做几番、酒醒天寒，唤山寺夜钟，水楼长笛。","万里苍茫，倩谁问、飞琼消息。","折梅花、故人故里，寄愁未得。"]},{"t":"解连环","f":"古风","c":["驿尘三辅。","向邮亭系马，晚钟敲雨。","看荒垣、几日清秋，恰疏柳当门，暗牵离绪。","半枕浮生，问短梦、今宵何处。","任吟笺香冷，画浊泪深，归思难赋。","滹沱去程记否。","料重寻往迹，爪印非故。","尽思量、南走邯郸，盼漳水铜台，旧乡云树。","唤客山灵，又相约、明朝西去。","寄愁心、雁飞雁落，夜长自语。"]},{"t":"金缕曲 芙初残腊抵京，况味寂寥，次韵赋赠","f":"古风","c":["玉斝春风暖。","尽宵深、炉香飘尽，烛花烧短。","店月桥霜经行处，缕缕梦魂谁管。","向竹里、今番重款。","别泪青衫痕犹凝，料琵琶、听彻歌声软。","闲细数，雁程缓。","征尘写入江南怨。","自沈吟、紫箫非旧，翠衾空展。","燕麦元都无人问，况是素弦声断。","更休诉、京华游倦。","鸥鹭江湖还漂泊，甚闲云、容易随舒卷。","回首处，晋陵远。"]},{"t":"金缕曲 夜坐叠前韵","f":"古风","c":["画鸭香心暖。","倚黄昏、岁残时序，漏长檠短。","官阁梅花开犹未，吹破一枝羌管。","念独夜、清尊谁款。","弹指春光天街近，渐东风、飏得红尘软。","吟拥鼻，数声缓。","金梁此夕啼鸦怨。","黯消凝、旧山图画，不堪重展。","烟梦凄迷无寻处，多事彩云吹断。","算顾曲、心情都倦。","唤起青鸾归飞去，看樊楼、十二珠帘卷。","千里外，寄愁远。"]},{"t":"三姝媚 樱桃","f":"古风","c":["垂檐红半亸。","渐饧箫吹残，荼蘼开过。","乍启唇朱，趁小腰蛮舞，玉颜初破。","禁苑偷衔，怜蘸羽、莺黄微涴。","记忆妆楼，闲折娇春，粉香千朵。","还对珍丛婀娜。","问露液承盘，为谁轻堕。","翠笼分携，送锦鞍归去，闷拈珠颗。","寄远年年，将恨与、鲛绡俱裹。","怕说杯停婪尾，繁阴梦锁。"]},{"t":"声声慢 偕邵季若自窑台步至江亭，菰蒲肃肃，殊有濠濮间意","f":"古风","c":["钩藤碍屐，带草牵衣，循途恰转回塘。","镜曲幽寻，疏磬渐引云房。","翛然半郊半郭，浣尘缨、惯咏沧浪。","听醉语，只山僧一笑，识我清狂。","回首前游几日，又西风吹换，石冷苔荒。","倦柳依依，犹恋澹薄秋光。","沙鸥漫留后约，怕重来、老却斜阳。","归未得，但凭高、远睨旧乡。"]},{"t":"声声慢 晨起踏雪诣向亭","f":"古风","c":["街长帽侧，径滑筇扶，斜风乍见飞绵。","款竹门深，还更一笑相看。","朝来玉楼冻合，怪尖叉、瘦耸吟肩。","闲趣好，但尘襟泥酒，醉墨涂笺。","容易烟云过也，甚鸿泥爪印，倦旅依然。","冷落诗囊，谁念岁晚长安。","冰霜待寻伴侣，只孤琴消得清寒。","似梦里，又梅花、开了故山。"]},{"t":"好事近 舆中杂书所见得四阕 其一","f":"古风","c":["杭苇岸才登，行入乱峰层碧。","十里平沙浅渚，又渡头人立。","笋将摇梦上轻舟，舟尾浪花湿。","恰好乌篷小小，载一肩秋色。"]},{"t":"好事近 舆中杂书所见得四阕 其二","f":"古风","c":["诗句夕阳山，扇底故人曾说。","好是固关西去，看万山红叶。","翠蛟潭上认题名，屐齿为君折。","蓦地藓花浓处，出一双胡蝶。"]},{"t":"好事近 舆中杂书所见得四阕 其三","f":"古风","c":["峻坂怯肩舆，引绠两行犹弱。","几日牵船岸上，只蒲帆难著。","一声碧月大堤头，旧梦定谁托。","何似春风天半，挽秋千红索。"]},{"t":"好事近 舆中杂书所见得四阕 其四","f":"古风","c":["引手摘星辰，云气扑衣如湿。","前望翠屏无路，忽天门中辟。","等闲鸡犬下方听，人住半山侧。","行踏千家檐宇，看炊烟斜出。"]},{"t":"丁香结 双柏堂偶述，用周美成韵","f":"古风","c":["屋角烟疏，井阑人寂，纤影月娥低陨。","叹流光轻迅。","玩素景、路指苔阶蓊润。","倦怀曾见否，新寒试、袖薄更忍。","天涯凝想，粉泪定逐炉香飘尽。","秋引。","正暗叶吟商，梦觉南云雁阵。","钿尺闲抛，纹衾静倚，一灯初晕。","凭寄归羽停息，送喜笺盈寸。","联萸屏清咏，犹及霜红未损。"]},{"t":"蹋莎行","f":"古风","c":["劝客清尊，催诗画鼓。","酒痕不管衣襟污。","玉笙谁与唱消魂，醉中只想瞢腾去。","绮席频邀，高轩惯驻。","闷来却觅栖鸦语。","城头一角晋阳山，怪他青到无人处。"]},{"t":"浪淘沙 拟游晋祠不果","f":"古风","c":["雉堞几凭栏。","拄笏空看。","丛祠依旧锁云关。","如此岚光浑不识，羞渡桑乾。","碧玉泻潺湲。","流水生寒。","一声凉雁最无端。","桐叶西风多少恨，留与青山。"]},{"t":"浪淘沙 秋蝉和衎石","f":"古风","c":["凉思又铜盘。","琴外声残。","一庭愁碧正相怜。","冷入秋心飞不去，衰柳年年。","何处说荒寒。","落叶长安。","西风休更倚栏干。","弱羽翛翛真似我，鬓影羞看。"]},{"t":"南楼令 归次寿阳驿，霜气寒甚","f":"古风","c":["候馆闭残釭。","凄凄夜已霜。","拥青绫、一昔云凉。","多事西风吹恨去，随冷月、度回廊。","秋梦恼疏狂。","征衣惜旧香。","有闲心、休著思量。","憔悴银屏山几叠，浑不耐、漏声长。"]},{"t":"丑奴儿慢 九月十九日望都县城外旧事","f":"古风","c":["轻尘倦马，酒醒今宵何处。","最愁说琼箫、花外半壁储胥。","恨入初程，剑歌声悄壮心孤。","围棋乘兴，迟回命屐，一著先输。","鼓吹未闲，凄凉官烛，憔悴军符。","更谁向、平原飞骑，笑挽雕弧。","废垒秋笳，怨吟曾到帐中无。","伤心休问，辽空唳鹤，残月鸣狐。"]},{"t":"高阳台 客有谈卫源近事者，感赋此调","f":"古风","c":["鸩羽惊媒，龙音感悦，匆匆芳讯偷传。","一纸相思，怨红啼湿银笺。","连波别有牵魂处，甚回文、倦眼曾看。","枉猜他，珠腕闲题，粉泪轻弹。","无情河水东流去，打空城寂寞，萤火飞残。","埋玉谁家，秦箫吹冷荒烟。","人间多少伤心事，误南柯、浅醉酣眠。","又争知，孔雀徘徊，还到郎边。"]},{"t":"高阳台 仙露庵，宋宫人饯汪水云处","f":"古风","c":["白雁声残，青蛾泪尽，燕台别路重分。","供奉琴歌，不堪弹入离尊。","兴亡梦短黄冠老，掩金觞、翠袖含颦。","叹西湖，卅六离宫，何处长门。","当年环佩空归去，任花幡恋雨，佛火愁人。","剩水残山，依然铃语黄昏。","红兜那觅南朝寺，话沧桑、旧额犹存。","泣铜仙，承露盘倾，一样消魂。"]},{"t":"高阳台 长椿寺明田妃画像","f":"古风","c":["叶落秋槐，花零素奈，惊鸿省识啼妆。","月影扬州，禁他燕馆清霜。","九莲寂寞闲房共，黯残僧、黄帕司香。","尽关心，小阁承乾，前度昭阳。","霓裳未破哀蝉诔，指环妃葬地，金碗银床。","天寿幽宫，珠旒翻托明珰。","相从好奏西陵伎，比人间、椒殿春长。","漫魂归，一帧芝龛，冷话兴亡。"]},{"t":"玉漏迟 耦庚席上赋葛仙米","f":"古风","c":["绀珠尘未扫。","幺禽啄后，碧螺痕小。","一捻圆匀，春出玉山香稻。","隽味青精漫拟，待糁入、羹汤还好。","春又早。","红盐绿酒，者时情抱。","相看句漏云封，只乞米长安，甑尘闲笑。","旅食年年，依旧石田荒了。","尽把丹砂寄与，怕梦里、黄梁人老。","乡信杳。","知他雁鸿多少。"]},{"t":"喜迁莺 过米市胡同作","f":"古风","c":["翻阶红药。","尚作意弄晴，雕栏西角。","金谷春迷，芜城天远，都把俊游抛却。","闷思去年花发，愁惹今年花落。","燕飞尽，问悠悠何处，桥边朱雀。","疏箔还更启，闲拂暗尘，梦短凭谁觉。","蜡泪黏萤，衣香化蝶，不记那回行乐。","旧欢断魂人往，新侣探芳人约。","赏心事，又从头听取，柔奴弦索。"]},{"t":"月华清 赋得团扇复团扇","f":"古风","c":["小影兜香，圆规倚月，未秋已自惆怅。","憔悴回看，几日乍萦蛛网。","记同心、有约相携，问半面、为谁羞障。","乌巷。","负僧弥玉润，绣奁偎傍。","戏蝶游踪暗想。","枉镜彩重重，细描宫样。","宛转声中，禁得倩魂摇飏。","掩花容、新恨仍迷，听絮语、旧情难忘。","低唱。","付秦淮渡口，那时双浆。"]},{"t":"月华清 初夏","f":"古风","c":["燕乳飞迟，蚕眠香老，一番婪尾吟后。","怕检罗衫，还怯晓寒襟袖。","蘸帘影、绿荫方重，寻履迹、艳阳难又。","孤负。","听鹂鹠花外，那回携手。","伴侣停针话久。","但强启窗纱，闷添晴昼。","栀子同心，忍见素纨描就。","悔抛却、吹絮光阴，任闲到、熟梅时候。","依旧。","试榴红群衩，为伊消瘦。"]},{"t":"月华清","f":"古风","c":["短策吟烟，骄骢践渌，柔波十里如剪。","一舸谁携，恰好径随花转。","乍唤侣、垂柳门边，更觅路、曲栏桥畔。","消遣。","向菱湾蓼溆，等闲寻遍。","况是澄湖涨满。","傍岸觜沙唇，镜奁初展。","银汉盈盈，可许浣纱人见。","带空翠、半角山孤，蘸秋影、数重天远。","归晚。","正冰绡索句，玉鞭须缓。"]},{"t":"绛都春 绿阴","f":"古风","c":["烟丝邃馆。","乍约住翠云，回廊遮遍。","做暝弄晴，沾惹离愁愁无限。","凄香滞粉闲凝眄。","更谁识、残红幽怨。","杜鹃何许，匆匆尽把，艳阳催晚。","空恋。","簪花俊赏，泥人处、暗里朱颜偷换。","问取倩魂，那信飞莺吹还转。","啼妆枉隔春风面。","剩黛色、眉痕犹见。","悄然青子枝头，恨长梦短。"]},{"t":"玲珑玉","f":"古风","c":["蓉缺樱残，早添得、韵事京华。","玻璃沁碗，唤来紫陌双叉。","妙手玎珰弄巧，胜肩头鼓打，小担声哗。","停车。","裁油云、隔住玉沙。","暗想槐薰倦午，正窗闲雪藕，鼎怯煎茶。","碎响玲珑，问惊回、好梦谁家。","屏间珠喉轻和，有多少、铃圆磬彻，低唱消他。","晚香冷，伴清吟、深巷卖花。"]},{"t":"玲珑玉 瓦喷壶","f":"古风","c":["清暑帘阴，晚风送、枕簟潇潇。","陶家制出，买春不是诗巢。","几阵阶前递响，早千丝玉溅，一白珠跳。","凉宵。","还相催、金井桔槔。","未拟官哥样好，但瓶长较颈，鼓细量腰。","贮腹泉甘，尚亏他、浅润堂坳。","壸公仙踪曾托，更休把、冰清心迹，瓦合轻嘲。","雨来也，扫烦襟、如意漫敲。"]},{"t":"望海潮 送勋楣出守琼州","f":"古风","c":["银泷飞盖，油幢溅雪，春风乍到南天。","闽峤句题，羊城路指，罗浮青入双鬟。","烟霭护旌旃，看沧溟咫尺，催渡楼船。","竹马人来，几声铜鼓唱喧闻。","吟心卧阁清闲。","正桄榔未老，蝴蝶犹仙。","蜑雨弄晴，蛮花醉晓，珊瑚十万琼田。","一酌试廉泉。","想深沈合浦，早有珠还。","扫尽楼台蜃气，吹笛海门山。"]},{"t":"琐窗寒 紫泉孝廉李宾石，余再从姊婿也。病树不春，昙花遽萎，莹莹嫠纬，其可哀也","f":"古风","c":["听雨沽春，题花卜夜，胜游曾几。","书传雁羽，有约玉箫同倚。","踏松阴、依然断肠，素弦一昔牙琴碎。","过招提倦旅，当时灯晕，尚飘红穗。","谁寄。","相思意。","但絮影埋香，酒痕吹水。","秋坟怨语，悽入女媭砧里。","话伤心、孤雏未将，纸钱那觅空燕垒。","判今生、尘面西风，为君持泪洗。"]},{"t":"齐天乐 寒云","f":"古风","c":["泬寥千里寒空色，谁教玉龙轻占。","望里仍飞，愁边又聚，不许梨花香泛。","阳台恨敛，漫提起巫峰，那回春感。","梦雨苍凉，楚腰羞向近来减。","探梅曾约旧崦，鹤衣寻径处，幽境空念。","澹欲黏天，浓应酿雪，赢得今番凄黯。","山螺翠掩。","更隐约疏林，墨痕低染。","界破冥濛，冷鸦三四点。"]},{"t":"齐天乐 寒月","f":"古风","c":["广寒已是销魂地，西风况禁凄恻。","鹫岭初升，鸳楼乍映，依约圆冰飞出。","澄辉似昔。","只酒罢春溶，梦孤秋碧。","漫忆前身，水精帘下又今夕。","青天重诉怨抑。","素蟾流影外，难寄消息。","悄倚娥妆，闲抛绿药，一杵元霜空惜。","瑶笙夜寂。","斗青女婵娟，误他孀魄。","泪点金波，任教菱镜湿。"]},{"t":"齐天乐 寒灯","f":"古风","c":["琐窗闲絮钗虫语，盈盈倩魂无定。","盏侧星孤，盘攲豆小，争忍挑来还晕。","瑶街漏紧。","待添了铜荷，玉膏犹凝。","夜饮谁家，九莲花底唤春醒。","兰房幽意自省。","背人茸帐倚，金鸭都烬。","半剪难胜，双心暗怯，长盼天涯芳信。","欢期未准。","任碧悴红迷，怨蛾相映。","绣被霜浓，一枝空照影。"]},{"t":"齐天乐 寒柝","f":"古风","c":["暮天吹角谯门断，凄音乍闻飘渺。","响接砧疏，传随箭急，还带提铃声小。","严城静悄。","伴清漏铜壸，几番昏晓。","逝水年华，为谁消领旧怀抱。","空街敲恨未了。","铁衣来往处，霜信偏早。","鹭堠迷烟，鸡筹唤月，那更春光不到。","离情暗恼。","问挑尽残灯，送愁多少。","帐底惊魂，夜长人易老。"]},{"t":"齐天乐 寒鸦","f":"古风","c":["晚霜天外归飞急，凄凄噤寒无语。","水驿樯稀，河堤树老，羞说垂杨终古。","酸风听取，问积霰平林，旧巢安否。","黯澹丛祠，阵云吹送楚江暮。","苏台前事暗数。","醉歌人未散，银箭催曙。","叫月声孤，栖烟梦冷，重忆昭阳何处。","萧条倦羽，怅子夜啼残，白头还苦。","鬓影相看，玉颜空泪雨。"]},{"t":"齐天乐 寒雀","f":"古风","c":["故枝惊说平林尽，霜天几回漂泊。","画舫烟迷，朱桥日暮，多少荒凉村落。","空仓去却，叹廷尉门前，哭饥谁托。","化蛤余生，水云何处梦难著。","枋榆重问旧约。","燕泥凋粉壁，一样萧索。","废垒闲寻，疏梅乍放，且喜幽香堪啅。","雕檐半角，更休忆华堂，那时行乐。","翠羽清啼，近来风信恶。"]},{"t":"新雁过妆楼 琴砚是宾石所赠","f":"古风","c":["晕墨凝香。","诗魂化、犹依片玉琳琅。","半规蕉叶，凉信暗剪秋霜。","泪眼研愁书懒寄，更无梦约紫泉庄。","黯情伤。","广平似石，特地回肠。","红丝当时共炙，借锦笺镂笔，写怨宫商。","断纹何许，年少惯倚疏狂。","而今赏音漫索，但目送西风归雁行。","相思处，在翠蟾铅水，盈盈一方。"]},{"t":"新雁过妆楼 冰簪","f":"古风","c":["漏咽铜签。","飞琼过、瑶笄误落雕檐。","峭风寒剪，新意幻出纤纤。","镂雪镌霜帘影下，镜台未怯晓晴占。","溜痕添。","悄移凤蜡，珠颗教衔。","犀椎敲来尚惜，衬绮疏翠幌，碧润偷拈。","弄妆呵手，春恨暗触晶奁。","鬟云更谁试插，但著指、防他清泪淹。","芳魂去，待化成娇玉、花香一篸。"]},{"t":"诉衷情","f":"古风","c":["芳径。","人静。","帘外影。","晓朦胧。","花信早。","颠倒。","任春工。","莺语隔房栊。","匆匆。","画楼今夜风。","是残红。"]},{"t":"诉衷情","f":"古风","c":["锦幔。","斜巷。","春意懒。","篆香微。","人去后。","杨柳。","又如丝。","无语对花枝。","依依。","小园蝴蝶儿。","恨来时。"]},{"t":"思佳客","f":"古风","c":["检点娇红瘦几分。","含情重问可怜春。","谁教南浦愁中絮，却化西楼梦里云。","吟翠管，步香尘。","小栏花影易黄昏。","后来怕见初弦月，才学蛾眉便学颦。"]},{"t":"思佳客","f":"古风","c":["帕上新题闲旧题。","苦无佳句比红儿。","生怜桃萼初开日，那信杨花有定时。","人悄悄，书迟迟。","殷勤好梦托蛛丝。","绣帏金鸭薰香坐，说与春寒总未知。"]},{"t":"思佳客","f":"古风","c":["寂寞湘帘下玉钩。","一春清景似残秋。","粉消蕙帐情空寄，花退兰釭恨未休。","银凿落，钿箜篌。","欢场那更问朱楼。","双蛾已是生来浅，禁得西窗此夜愁。"]},{"t":"思佳客","f":"古风","c":["梦语惺忪记未真。","起来还倚退红茵。","绿腰枉自翻新曲，蓝尾谁能惜好春。","金剪歇，玉炉薰。","懒将纤手试寒温。","人间无著相思处，剩检罗衣看泪痕。"]},{"t":"思佳客","f":"古风","c":["尘壁凭谁护绛纱。","西风凉处见秋花。","知音渺渺怜人世，薄命依依念岁华。","吟蕙草，怨郀瓜。","吴淞飞絮又天涯。","一春梦雨伤心事，休问江南燕子家。"]},{"t":"尉迟杯 何仙槎前辈席上作，仙槎大为击节，此醉语耳，不自知其辞之所以然","f":"古风","c":["欢娱事。","甚著眼都作凄凉字。","无聊漫写云笺，那复前尘犹记。","红牙妙谱。","也尽许、歌喉按新制。","又争知、凤牒重看，俊游空付流水。","馀香醉拍征衫。","怜刀剪、并州蟏网长系。","冷落花名，人谁识珠，泪裹乌栏半纸。","如今纵、天河倒泻。","料难望、银钓墨晕洗。","但从他、试语初莺，自寻墙外桃李。"]},{"t":"梦横塘 荷叶似云香不断。白石句，以慢词写之","f":"古风","c":["液池擎艳，渌沼含馨，湿云飞满凉翠。","千叶香心，荡三十六湾秋意。","倚盖天长，浣衣人杳，卷波无际。","认珠盘冷浸，一抹横塘，重重碧、重重水。","嫣红半落谁怜，但参差远影，还蘸吟袂。","鹭送鸥迎，料未许、夕阴吹碎。","唤小艇、青奁摇梦，待觅风痕过烟尾。","甚日开门，藕花多处，约词仙同醉。"]},{"t":"江城梅花引","f":"古风","c":["一双银蒜暮丁冬，是东风。","是西风。","吹得疏疏，凉雨打梧桐。","沈水半消金鸭冷，人不见，梦依依、唤玉骢。","玉骢。","玉骢。","无路通。","步霜红。","霜更浓。","过也过也，过不了、咫尺帘栊。","依旧相思，围住画栏中。","推枕起来还欲睡，楼角外，又萧条、听断鸿。"]},{"t":"菩萨蛮","f":"古风","c":["竹梧重叠交窗影。","水纹簟卷冰花冷。","灯穗堕空烟。","梦回秋可怜。","玉阶人不见。","络纬啼成怨。","银汉信沈沈。","碧云深更深。"]},{"t":"菩萨蛮","f":"古风","c":["门前帘幕垂垂护。","出门待索银蟾语。","圆影可怜低。","晓风吹又西。","十三弦上意。","筝柱还摇曳。","听到别情无。","一声金雁孤。"]},{"t":"菩萨蛮","f":"古风","c":["映门衰柳无颜色。","长条一夜西风急。","人倚小红楼。","栏干天际愁。","愁来天又暮。","艇子冲波去。","打桨问鸳鸯。","鸳鸯秋梦长。"]},{"t":"菩萨蛮","f":"古风","c":["曲栏低亚凉波净。","回风绿蘸烟芜影。","烟外几人家。","天涯即水涯。","莲衣寒恻恻。","蕙带搴无力。","到此合魂消。","冷香黏画桥。"]},{"t":"菩萨蛮","f":"古风","c":["玉簪浥露情怀重。","海棠冷落西川梦。","掩映几枝斜。","瘦痕秋在花。","苍苔馀缱绻。","履迹闲寻遍。","无处问东风。","乱鸦残照中。"]},{"t":"菩萨蛮","f":"古风","c":["夕炉晨佩江淹句。","当年南浦愁人处。","衰草恋斜晖。","王孙归不归。","悽悽秋社语。","梁燕仍羁旅。","倦尾路双叉。","乌衣何处家。"]},{"t":"菩萨蛮","f":"古风","c":["玉楼云散花憔悴。","紫泉月冷重门闭。","门外夜乌啼。","伤心闻捣衣。","团团争忍见。","画箑愁无限。","何处去年人。","酒痕沾泪痕。"]},{"t":"菩萨蛮","f":"古风","c":["草桥买尽麻姑酒。","醉来系马桥边柳。","漂泊十年闲。","离情山上山。","秣陵书懒寄。","旧约空弹指。","泉路断肠时。","人闲谁复知。"]},{"t":"洞仙歌 宾石曩主钟仰山侍讲家最久，偶访旧馆，怆然黄垆之思。用玉田观花外集有感韵","f":"古风","c":["燕归何处，过乌衣门第。","一带轻烟隔秋水。","叹衫痕、晕酒琴语弦诗，三十载，尘世赏音无此。","吟魂犹在否，几叶云笺，澹墨重寻旧题字。","梦蝶不归来、镜里芙蓉，剪霜影、一枝红碎。","有邻笛、依依故人心，问蜡炬、成灰夜台知未。"]},{"t":"相见欢","f":"古风","c":["炉香冷了金猊。","镜台携。","不信生来长见，翠眉低。","春梦断。","画阑畔。","旧情迷。","刚是晓鸦啼后，子规啼。"]},{"t":"相见欢","f":"古风","c":["一丝秋入雕梁。","燕双双。","蓦地庭梧已做，十分凉。","楚竹簟。","越罗扇。","漫思量。","咫尺画栏西畔，是斜阳。"]},{"t":"清平乐 忆梅","f":"古风","c":["寻寻觅觅。","竹外人孤立。","砑粉银笺题又湿。","冷却翠禽消息。","旧时芳讯依然。","而今幽恨年年。","一笛绮窗归梦，故山无奈春寒。"]},{"t":"扬州慢","f":"古风","c":["银管拈愁，玉笺封泪，十年人老藤花。","趁飞凫小影，又敛翼京华。","认当日、题名醉墨，翠阴深处，重拂窗纱。","话风流、裙屐多时，香散蜂衙。","旧游过眼，漫低回、身世抟沙。","叹候馆凄灯，归艎倦枕，残梦谁家。","唤起二分明月，芜城怨、写入啼鸦。","但潮生潮落，秋声容易天涯。"]},{"t":"忆旧游 题画","f":"古风","c":["向生绡托兴，缥缈襟期，刊落尘缘。","异境无人到，望瑶岑矗笋，玉井开莲。","冷光半湿幽翠，烟影散虚坛。","想万壑松风，珠庭近接，渺矣高寒。","灵源。","竟何许，有几片桃花，流出云间。","漫说丹邱隔，便移家好住，谁耐清闲。","石床自写琴意，空外揖群仙。","待月白千峰，相携跨鹤天际看。"]},{"t":"天香 水仙花","f":"古风","c":["水艳吟香，花情眷梦，湘皋记共游冶。","盏侧涂金，簪横削玉，雾带碧痕低亚。","通词试托，问甚日、仙魂初化。","翠羽明珠不见，依然冷云凝夜。","银釭旧愁自写。","倚冰奁、薄寒吹麝。","一掬茜窗清泪，粉妆慵卸。","还恐春风唤起，又暗忆、扁舟古祠下。","素袜无声，凌波去也。"]},{"t":"绿意 冬蕉","f":"古风","c":["墙阴翠擢。","记绿天深处，题翰曾约。","黯黯吟魂，恻恻寒宵，禁他瘦倚栏角。","多生已苦秋窗雨，况梦影、霜华凋落。","尽故人、书叶留看，早是怨怀难托。","谁倩瑶函寄语，寸笺料未许，春信偷觉。","一束相思，可奈伶俜，惯与西风梳掠。","缄愁缄恨还缄泪，任蜡样、芳心抛却。","待雪残、重结清游，好觅辋川池阁。"]},{"t":"摸鱼子 长至前夕，偕芙初、琴南饮衎石斋中偶述","f":"古风","c":["浣冰毫、擘笺题句，宵分绛蜡重剪。","玉珂风外闲身在，恰趁翠尊寒浅。","梅信缓。","问半萼、吹香瘦影供谁眷。","天涯念远。","但兰佩浮湘，桐圭访古，长记故人面。","新声倚，换羽移宫难惯。","旗亭按拍都倦。","宣南坊里联吟处，只有盍簪堪恋。","尘梦短。","算买得、莺邻何必论乡县。","荷衣倘换。","驾一叶沙棠，吴根越角，要结鹭鸥伴。"]},{"t":"梦芙蓉","f":"古风","c":["芳游迷艳绮。","认颓垣古甃，蔓萝交曳。","画阑回首，零落旧题字。","断魂烟雨里。","绿珠门小应闭。","半角西山，知颦蛾怨晓，曾否黛痕洗。","好句屯田漫拟。","一酌清冷，识曲今谁是。","鬓丝风影，人与露桃悴。","素波浑不起。","鹿卢修绠空系。","梦隔仙源，但银瓶信杳，难问绛河水。"]},{"t":"摸鱼子 读元遗山芳华怨乐府漫题","f":"古风","c":["黯消魂、故宫遗事，金源旧恨重数。","鹍鸡弦上芳名认，一片冷云吹雨。","都尉府。","忆阿海、香闺近接东华路。","承恩未许。","但褪粉妆残，迎秋扇薄，还送燕归去。","娃儿曲，枉了巫峰朝暮。","银红休按花谱。","花开花落天难问，莫为绿鬟深诉。","君记取。","只几日、青城寂寞春无主。","人间最苦。","算杜宇声声，摩诃院里，才是断肠处。"]},{"t":"摸鱼子","f":"古风","c":["送归人、去帆两两，平芜千里如剪。","分襟忆到题襟日，又早蜡梅香浅。","鱼素缓。","空领略、淮河津口魂双眷。","天长水远。","怕星饭填愁，尘衫涴泪，难认旧时面。","东华客，十日闭门都惯。","相如今更游倦。","鸳湖鹤市空中想，翻是他乡情恋。","吟兴短。","漫赢得、秋来梦不离江县。","吹葭节换。","试问讯刘郎，深杯雪屋，灯影剩谁伴。"]},{"t":"摸鱼子 和潘吾亭同年再叠前韵","f":"古风","c":["倚香篝、小楼听雨，春衫谁与裁剪。","潞河桥下波千尺，比似别情还浅。","腰带缓。","更海燕、传书碎语增悽眷。","琼枝恨远。","恁夜舮牵衣，垂髫断影，长隔镜中面。","城南路，乌帽黄尘行惯。","新诗水部吟倦。","西湖西子频牵梦，未信软红犹恋。","生计短。","只地上、裁花那是君家县。","思乡酒换。","剩玉雪佳儿，芸编问字，灯火纸窗伴。"]},{"t":"摸鱼子","f":"古风","c":["野桥西、霁岚千叠，攀萝待访深隐。","钟鱼记否曾来处，一衲故吾堪认。","莲漏紧。","任小梦、眠云也觉岩栖稳。","芒鞋晓趁。","道咫尺龙堂，山灵唤客，一径入秋蚓。","还惆怅，早是琼苞香褪。","瑶台空堕珠粉。","看花眼冷春明路，花里翠禽知恨。","泉更引。","照镜底、青螺懒说仙源近。","催归未忍。","料倚杖哦松，题笺选石，后约总无准。"]},{"t":"摸鱼子 暮春遍游近郊诸兰若，觉生寺大钟、万寿寺白皮松尤胜赏也","f":"古风","c":["散幽襟、近郊春晚，香台游屐争试。","半幡风外招寻惯，吟思塔铃遥坠。","阴满地，望不断、霜皮雪干松烟翠。","钟楼倦倚。","待磨洗前朝，鲸鱼篆刻，梵夹几行字。","僧寮话，花影竹房深闭。","落花更扫阶砌。","杏坛管领春风帚，我亦官闲如此。","清磬里。","浑未识、禅心宦味都相似。","诛茆便拟。","指苍卜林西，斜阳一线，山在冷云背。"]},{"t":"摸鱼子 叠前韵为衎石赋雁影庵，时将移居玉河桥","f":"古风","c":["卜幽居、石桥西堍，衡茆蒋径催剪。","匆匆过影还留影，恰照玉河清浅。","筝柱缓。","倚绣阁、双声一例神仙眷。","香心寄远。","比旧日褊褼，罗浮粉翅，长印镜澜面。","城南宅，传舍年来栖惯。","多应素羽飞倦。","云何桑下曾三宿，翻恐俗缘生恋。","秋梦短。","又谁道、等闲衾枕非乡县。","蘋渔谱换。","算小字题笺，凉音唤侣，我亦水云伴。"]},{"t":"摸鱼子 衎石迁居未果，重拈前韵为雁影庵问","f":"古风","c":["认巢痕、一枝初定，禁他客燕双剪。","玉河最好嬉晴渌，偏是诗人缘浅。","新句缓。","枉付与、春波桥下鸥情眷。","会心未远。","且回首吾庐，江亭咫尺，绕舍水三面。","君知否？","雁影澄潭留惯。","衔芦到此应倦。","菰蒲叶叶幽寻近，料也雪泥还恋。","尘袂短。","又何必、衡云定觅湘南县。","归飞羽换。","但寄意潘郎，笺传素翼，莫忘旧吟伴。"]},{"t":"望湘人 石黼庭同年以画兰索题，戏拈此调","f":"古风","c":["记幽坊唤酒，佳节试灯，翠屏新曲曾顾。","冶叶柔情，媚香妙谱。","小影华年偷诉。","皓腕清襟，楚骚遗韵，仙裳休妒。","正石家、金谷留看，底事花随春去。","愁思江南路阻。","叹凌波步远，袜尘难驻。","问解佩吴宫，可似梦云湘汝。","灵根种，恨风条传语。","那识题笺心苦。","不忍见、一纸芳魂，化作横塘烟雨。"]},{"t":"澡兰香 重午用梦窗韵","f":"古风","c":["闲情斗草，雅戏牵钩，节序被人唤觉。","银澜荡桨，镜曲分笺，长是梦游空约。","盼飞凫、音信难凭，相思榴红破萼。","小簟凉痕，困倚汀蒲洲蒻。","重话河桥往事，细葛风前，暗消吟魄。","尘梁去燕，彩箑招蝇，枉却绀纱帷幕。","试兰汤、新浴还慵，谁伴芳尊共酌。","但认取、艾叶朱符，馀香襟角。"]},{"t":"澡兰香 蝶茧和小云韵","f":"古风","c":["罗浮旧侣，仙迹曾栖，一剪洞云溜碧。","花迷试梦，橘蠹淹秋，怡好舞衣藏得。","问匆匆、粉怨香愁，情丝因谁暗织。","壁镜分明，可念春来消息。","看取团栾样巧，中有柔奴，玉腰纤魄。","翾飞小影，阅到枯形，密绪尚怜攲侧。","付兰闺，掺手亲缫，却恐蚕娘未识。","剩几片、芳草宫斜，罗裙空忆。"]},{"t":"高阳台","f":"古风","c":["黄叶风多，青苔篆蚀，残碑尚认啼痕。","怨魄归来，愁他蛱蝶罗裙。","一弦一柱哀琴语，打群莺、枝上消魂。","最无端，玉骨凄凉，娟袂难分。","娃宫谁问伤心史，只潘花小字，犹纪贞珉。","妙墨重镌，依然金碗千春。","埋香那觅三兴土，掩颦蛾、灰冷齐云。","但从今，墓草年年，休长情根。"]},{"t":"高阳台 用碧山韵答衎石潞河舟次之作，兼怀琴南","f":"古风","c":["帆角攲烟，船唇坠叶，一番凉雨澌澌。","惜别山容，城尖仍倚愁眉。","潘河门掩珠巢冷，问紫骝、可记当时。","正无聊，醉醒厌厌，还倒金卮。","澄窗几写怀人句，寄垂虹南北，两地相思。","缟夜清霜，梦魂依旧来迟。","来时定折赛梅赠，道此情、惟有花知。","但凄然，鬓影缁尘，青镜成丝。"]},{"t":"高阳台","f":"古风","c":["鹊语偷传，乌栖暗警，宵分又驻鸾车。","七载重看，秋期弹指无差。","瑶阶拥帚知何事，劝凤翎、休扫闲花。","话仙都，小劫匆匆，愁里年华。","巫云漫逐西风去，听黄鸡怨曲，往事空嗟。","酒冷芳尊，可堪残醉消他。","盈盈尽隔牵牛渚，问情波、流恨谁家。","但思量，咫尺银湾，不是天涯。"]},{"t":"满庭芳 辽后洗妆楼","f":"古风","c":["眠柳梳烟，荒池洗月，翠帘不卷春愁。","暗尘珠络，芳艳未全休。","飞燕新词漫拟，簪花格、墨妙谁偷。","凭栏处，靴金帕玉，肠断旧风流。","凝眸。","佳丽地，脂函镜匣，乡冷温柔。","但捺钵当时，谏草还留。","可惜琵琶调苦，回心院、枉费绸缪。","焚椒恨，天书练影，三十六宫秋。"]},{"t":"绮罗香 车帷","f":"古风","c":["绣幕围香，文裀藉玉，一夕屏星催换。","怯试秋心，恰好梦深寒浅。","认罽密、犀押匀排，爱绒唾、蝶衣新剪。","问流苏、四角低垂，越娥网住定谁见。","骄骢佳约未准，刚是虾须替却，圆晶双绾。","云母轻盈，藏得几分春怨。","似相看、帐里花枝，漫暗忆、镜中人面。","盼愔愔、油壁归来，画帘风外卷。"]},{"t":"绮罗香 香篝","f":"古风","c":["蕙炷藏春，湘筠借暖，曾说秦宫遗制。","金屋携来，有约镜边帘底。","描一幅、象篾疏花，护几片、鹊炉沈水。","向烟丝、认取檀痕，断魂谁与篆心字。","茧釭红穗未减，想见都梁乍爇，银屏无睡。","犀蝶双双，解了又还重倚。","好商量、坐久添衣，自消领、夜阑偎被。","尽从他、画鸭烧残，绣帏慵更启。"]},{"t":"琐窗寒 风窗","f":"古风","c":["翠箔收寒，琼钩捲月，一番风紧。","疏棂半掩，隔断满阶秋影。","蘸银笺、油花暗滋，午妆粉指新留印。","怕重来燕子，小门深闭，旧巢难认。","方镜。","颇黎衬。","更玉坠低悬，兽钚相并。","朱绳细绾，比似井栏斜引。","玳梁深、轻笼篆烟，绣帏窥处还易暝。","未愁他、画烛屏前，下帘红袖冷。"]},{"t":"琐窗寒 集贤院连雨","f":"古风","c":["润逼窗纱，凉侵簟竹，顿添憔悴。","将徐又紧，做出几分秋意。","对银屏、幽怀暗牵，素衾清梦谁料理。","最怜他此日，纹疏静掩，夹衣初试。","空指。","前游地。","任罥石苔滋，井栏愁倚。","回波涨晚，翠点一池萍碎。","带苍烟、归鸦倦飞，暝阴未破云更起。","但虚空、冷荡柔丝，远天都是水。"]},{"t":"琐窗寒","f":"古风","c":["扫叶门深，冲泥苍浅，雪残犹凝。","清言伫久，依约夕阴吹暝。","怪衙参、催归太迟，忍寒负却黄花等。","对藤枝络架，晚来还是，冻禽声静。","萍梗。","终无定。","正话到城南，者番邻并。","河桥旧约，又说玉虹腰冷。","占新巢、谁家画梁，笑人忙剧春燕影。","问何年、三塔吟莺，唤教乡梦醒。"]},{"t":"采桑子","f":"古风","c":["人间谁是消魂者，昨日鸾琴。","今日霜砧。","三日离愁海样深。","郁金香冷知何处，怅望春阴。","领略秋心。","绿蜡前头泪不禁。"]},{"t":"采桑子","f":"古风","c":["十三数到哀筝柱，憔悴牵牛。","鹊驾难留。","银汉桥边一夜愁。","从今怕说黄姑渡，短梦悠悠。","旧事回首。","但见秋光莫上楼。"]},{"t":"采桑子","f":"古风","c":["纸灰飞遍关山路，山也重重。","水也重重。","滴尽珍珠酒不浓。","双栖漫谱雕梁曲，花也匆匆。","月也匆匆。","燕子归来似梦中。"]},{"t":"喜迁莺令","f":"古风","c":["绿飞绵，红退萼。","芳景故凄迷。","不堪花信到将离。","刚是断肠时。","金雁筝，钿雀扇。","争似旧时曾见。","情丝牵断梦魂中。","枉自费东风。"]},{"t":"喜迁莺令","f":"古风","c":["梦缠绵，魂怨抑。","前事漫思量。","朱楼高处见垂杨。","那信是他乡。","莺自怜，花自惜。","此意甚人知得。","缕金鸂鵣绣罗襦。","曾有泪痕无。"]},{"t":"风蝶令","f":"古风","c":["唾碧凝痕重，流黄照影迟。","姮娥依旧弄清辉。","我自不曾真见、月圆时。","蝶恋前宵粉，蛛牵后夜丝。","酒边心事问伊谁。","除下镜光灯影、少人知。"]},{"t":"风蝶令","f":"古风","c":["琴语回瑶轸，帘波暗玉钩。","芳心一寸正难留。","消得三分病与、七分愁。","药裹抛仍在，苔笺卷款收。","薄寒无赖倚罗裯。","可是禁愁禁病、又禁秋。"]},{"t":"浣溪沙","f":"七言古诗","c":["谁筑闲园倚近坰。","小山丛木带回汀。","等闲水石费经营。","珍馆几时学旧迹，绮楼无地著春情。","蛛丝异兴可怜生。"]},{"t":"浣溪沙","f":"七言古诗","c":["绀瓦雕甍想像间。","薄阴吹冷土花班。","几人指点旧平泉。","桥水暗敲珠错落，岩云低映玉孱颜。","当时祇认是家山。"]},{"t":"浣溪沙","f":"七言古诗","c":["竹石三分水二分。","水边蜂蝶易消魂。","不堪重忆旧时春。","可有青苔黏画屧，似闻芳草斗罗裙。","丁香花榭不开门。"]},{"t":"浣溪沙","f":"七言古诗","c":["护玉笼香翠阁幽。","名花对影看梳头。","此中人说是迷楼。","夹幕暗通筝阮语，重帘分管燕莺愁。","紫云何处恨悠悠。"]},{"t":"浣溪沙","f":"七言古诗","c":["车马如云待漏迟。","未明天已玉骢嘶。","绿波桥上漫依依。","过眼绮罗犹昨日，伤心冠盖似当时。","无因说与白鸥知。"]},{"t":"浣溪沙","f":"七言古诗","c":["鞭影匆匆指落霞。","轻衾凉簟定谁家。","不辞小立倚汀沙。","但有藤萝皆映带，更无藻荇不横斜。","生怜消瘦到秋花。"]},{"t":"浣溪沙","f":"七言古诗","c":["扇底风痕弄夕凉。","酒醒人试藕丝裳。","新蟾钩样照横塘。","蝉雀有时还独语，凫鹥何必定同行。","澹烟清梦怕思量。"]},{"t":"浣溪沙","f":"七言古诗","c":["白鹤凭谁信手招。","银澜对影转无聊。","闷来何计觅双桡。","秋思可堪人寂寂，仙源依旧路迢迢。","微波原自不通潮。"]},{"t":"浣溪沙","f":"七言古诗","c":["泻地银河到海迟。","横波脉脉信来稀。","梦回吟得水乡词。","繁塔又添垂钓处，夷门恰有唤船时。","断肠风景定谁知。"]},{"t":"浣溪沙","f":"七言古诗","c":["带水何心说故乡。","隋堤秋色夜传觞。","可堪衰柳玩清霜。","仙手有人抛月斧，通眉无句觅诗囊。","禁他冶叶不凄凉。"]},{"t":"浣溪沙","f":"七言古诗","c":["冰雪河梁不见春。","欲回星汉问迷津。","此中何限未招魂。","尚有燕莺争暖树，可怜蜂蚁是微尘。","等闲天气判寒温。"]},{"t":"浣溪沙","f":"七言古诗","c":["倦眼凄迷望转赊。","悔将梦语托星槎。","春明门外似天涯。","乌鲗书成还易灭，青鸾信好未应差。","一年春事又桃花。"]},{"t":"鹊桥仙 龙须席","f":"古风","c":["桃枝逊滑，藤根让洁、八尺风漪铺水。","象床谁与问遗簪，有几点、瑶池清泪。","冰丝细袅，花纹巧织。","还似鲛宫新制。","任人舒卷总无心，不化作、凄凉云气。"]},{"t":"三姝媚","f":"古风","c":["交枝红在眼。","荡廉波香深，镜澜痕浅。","费尽春工，占胜游惟许，等闲莺燕。","步屧廊回，盈退粉、蛛丝偷罥。","小影竛竮，冷到梨云，便成秋苑。","容易题襟催散。","又酒逐花迷，梦将天远。","系马垂杨，但翠眉还识，旧时人面。","暗数韶华，空笑我、樱桃三见。","胜有盈盈胡蝶，西窗弄晚。"]},{"t":"三姝媚 马湘兰眉子砚为程春海同年赋","f":"古风","c":["蟾蜍清泪洒。","晕脂痕犹新，粉光初砑。","翠斫妆楼，比石桥新月，自矜声价。","斗叶闲情，偕象管、鸾笺消夜。","悄灸红丝，沈水浓薰，枣花帘下。","仿佛冰姿妍雅。","恰手撚兰枝，练裙歌罢。","槿艳无多，问坠鞭人去，秀蛾谁画。","往事含颦，随梦影、铜台飘瓦。","认取南都遗迹，青溪恨惹。"]},{"t":"三姝媚 己卯中秋","f":"古风","c":["澄辉看渐展。","数圆期禁他，绛霄人盼。","盼到良宵，又露华啼湿，一规珠汗。","镜彩分明，忆路隔、银桥曾见。","竟夕相思，青嶂魂迷，玉楼吟倦。","何处霓裳歌按。","但药杵声停，粉奁妆换。","困倚天香，赋旧情争被，晓风吹断。","破斧谁携，空暗结、吴郎秋怨。","望里山河小影，轮孤梦短。"]},{"t":"催雪","f":"古风","c":["帘罨重阴，灯晕半花，密坐贪依屏背。","语冷宦心情，竹深门闭。","客似寒鸦瘦影，惯倦羽、相偎银云底。","琴边试问，清宵款语，冶游知未。","燕市。","十年矣。","是几度分襟，几番搴袂。","又朔雪，关山岁华如此。","尽觅红螺换酒，酿不到、鳞鳞鸳鸯水。","料只有、藤角吟笺，犹认月波题字。"]},{"t":"丁香结 灯花和衎石","f":"古风","c":["窥幕蛾轻，缀窗萤小，烟影玉荷低衬。","是几番风信。","恰唤起、细朵盈盈红晕。","似华还似萼，妆台倚、笑靥未稳。","无端三点，两点惯向绡帏偷印。","芳讯。","比钿盒占丝，料得欢期渐近。","借暖根扶，含津蒂著，暗牵方寸。","良夜鸳枕睡觉，絮语空传恨。","凭钗虫飞去，说与春来瘦损。"]},{"t":"瑶花 吾亭偶谈汴中春觉菜之美，余不尝此味亦十载矣","f":"古风","c":["雪残近陌，压担泥香，记腰镰亲觅。","鲜芽破冷，新翠剪、几缕冰痕犹湿。","厨娘好语，道一信、花风先识。","伴罽袍、公子樽前，恰认稚春颜色。","铜街饯腊频番，枉十度春来，芳讯长寂。","愁春未醒，惟是有、海燕曾传消息。","庾郎清瘦，况隽味、乡园空隔。","但五辛、盘底年年，梦绕玉津萋碧。"]},{"t":"真珠帘 春影","f":"古风","c":["艳阳画出三春景。","漾空濛，几缕春魂犹凝。","摇曳絮飞时，弄琐窗烟冷。","一桁轻丝吹不断，被燕剪、捎来难定。","幽境。","尽看朱成碧，玉栏闲凭。","何处。","笑倚娉婷。","有娥池省识，东风妆靓。","半面倩谁描，更柳遮花映。","偷眼蜻蜓窥未足，似镜里灯前曾并。","人静。","奈帘波、缓荡碧云催暝。"]},{"t":"瑞龙吟 拟周美成","f":"古风","c":["吟香路。","重认泪点娟筠，唾痕芳树。","依然咫尺天涯，断魂絮影，知他甚处。","信音伫。","还是坠蛛尘网，半捎窗户。","无聊强揩红笺，醉来试倩，流莺寄语。","惆怅雕栏犹在，晚花羞眄，垂杨慵舞。","应想旧时堂前，巢燕非故。","琴心赠别，颠倒闲词句。","何曾见、珠帏夜悄，银屏微步。","佩解人归去。","帕罗尚绾，愁丝怨绪。","帘底波千缕。","空负我、西窗秋衾凉雨。","话残梦里，一灯谁絮。"]},{"t":"念奴娇 己卯五月十四日，集贤院池上忆壬申丙子与琴南两度游此，用白石韵","f":"古风","c":["万荷深处，话闲云，曾约同舟仙侣。","一叶浮香人不见，还对冷红无数。","此际江南，娟筠小簟，坐稳横塘雨。","相思赋就，画屏多少新句。","笑我尘鬓丝丝，回澜照影，花里频来去。","半枕圆波，鸥外梦、空到沙汀烟浦。","钓线垂风，吟鞯倚月，谁解留人住。","微茫雉堞，柳边愁认归路。"]},{"t":"惜秋华 耦庚继室郑宜人哀辞","f":"古风","c":["赋笔催妆，映宫袍、秀色鸾钗相倚。","春枕正酣，惊心杜鹃啼起。","前番泪湿湘筠，赖梦好、扬州重缔。","嫣香，更匆匆、褪却蕃釐仙蕊。","怊怅画屏底。","叹明珠乍剖，枉悬娇帨。","镜台近、绣褓认，几回凝睇。","人闲过眼空花，但锦裀、倩魂犹系。","愁悴。","问他年、左芬知未。"]},{"t":"金盏子","f":"古风","c":["彩笔休拈，锦字慵题，病馀无力。","又坠叶吟秋，疏棂外、闲了翠云消息。","懒听桂苑啼鸟，引琼箫悽恻。","西风泪、花冷素蟾，偏是广寒人只。","倦燕忽如客，待归去、苍烟暗故国。","沈沈绣帘易隔，宵来梦、比似曲屏还窄。","看取小扇尘生，嗟空箱抛掷。","消魂处、愁缕恨丝，机声催织。"]},{"t":"金缕曲 次日见吾亭词，倚调和之","f":"古风","c":["桂苑悽芳讯。","黯消魂、亭亭镜影，做成眉晕。","碧海青天依然在，偏是圆规难认。","漫重溯、春前幽恨。","两度伤心秋更苦，料嫦娥、泪也金波陨。","千里梦，几曾准。","清游但说良宵近。","望婵娟、瑶台笛里，旧情休问。","羽盖霓旌经行处，天路闲愁无尽。","待传语、纤阿纡轸。","露脚斜飞银兔悄，绛霄长、谁寄人间信。","灯炷落，漏声紧。"]},{"t":"应天长","f":"古风","c":["莺花近甸，鸿雪去程，依稀梦境堪觅。","记否那回携手，汀波恋馀碧。","垂虹影，还自直，有几许、倩魂消得。","画眉冷，走马人来，鸥鹭曾识。","回念别离时，陌上香泥，罗带为谁拭。","怕说绣鞯行处，鞭丝堕秋色。","前踪认，如过翼。","尽唤起、暮愁千尺。","断桥外，细雨恹恹，重问村驿。"]},{"t":"陌上花 题仙山图","f":"古风","c":["神山望里分明，幻出玉楼珠榭。","碧晃金迷，榄取几多姚冶。","仙源近接长生路，髣髴紫兰人下。","眷游情、不是闻风元圃，等闲图画。","漫相看、梦影雕甍倚处，月斧云斤无价。","凤管吹空，一曲绮筵歌罢。","天钱辛苦谁赢得，却向黄姑亲借。","但沈吟、怕说冰夷飞盖，翠澜生也。"]},{"t":"解连环 九日登香山北麓宋普庆禅师塔院","f":"古风","c":["晚秋西郭。","趁车尘路隔，胜游初约。","步静窈、几折云林，早岭接梵宫，涧横经阁。","片碣招寻，道舍利、当年曾托。","叹沧桑过眼，古井断垣，还见归鹤。","风铃甚时唤觉。","话南朝旧事，几度花落。","向定里、佳节重看，又积藓暗封，柳边门钥。","未冷禅心，为白雁、飞来愁著。","任匆匆、载诗载酒，翠屏半角。"]},{"t":"解连环 和片玉韵","f":"古风","c":["寸笺休托。","诉幽襟忍见，赋情绵邈。","耐书永、闲拂蛛尘，但锦羽梦孤，翠绡绿薄。","似水春阴，总化作、残秋萧索。","对厌厌病枕，闷损镜妆，谁寄灵药。","芳尊自开下若。","带颦蛾酒晕，犹倚栏角。","枉盼断、淮上青山，渺天际黛痕，等闲迷却。","浪迹依然，把柳絮、看成桃萼。","劝清游、半晴半雨，趁花未落。"]},{"t":"浪淘沙慢","f":"古风","c":["梓桑路、沙屯废馆，浪拥荒驿。","空约传书素翼。","乡心万缕似织。","任极望南云天咫尺。","远山外、烟影难觅。","断梦倚斜阳黯无语，虚堂自愁入。","悽忆。","涨痕旧隐抛掷。","傍岸柳依依，凝眸处、泪雨都暗滴。","嗟岁晏哀鸿，零乱谁宅。","绣衣画戟。","知甚时骢马，相逢人迹。","菱镜光销腰围窄。","年华晚、坐看箭激。","料应比、湍波流更疾。","恨归去、不附星查，十二载，尘衫冷透长安陌。"]},{"t":"庆春宫","f":"古风","c":["瑶瑟春愁，铜盘铅泪，寸缄冷护残雪。","冰缕方凝，尘封初启，玉簪小翠堪捻。","袜罗归去，正回想、飞琼话别。","相思天上，鹅管凄凉，为伊吹彻。","汉皋佩杳谁怜。","剪叶移根，几番悽绝。","悄梦禁寒，微波写影，应是香心犹结。","曲屏吟绕，怪诗屐、宵来渐折。","仙魂凝盼，出水亭亭，半眉新月。"]},{"t":"东风第一枝 十二月廿一日立春，时快雪三日矣","f":"古风","c":["帖剪宜春，诗吟饯腊，重阴偏滞檐角。","篆烟企鸭仍含，艳情翠禽未觉。","韶华唤醒，似梦里、东君曾约。","甚晓来、赏柳评花，还是冻云迷著。","风乍起、彩幡易落。","寒更峭、麝篝漫却。","俊游拟拂银鞯，倩魂尚偎绣幕。","天边絮粉，且休问、阳梢红萼。","待画鼓、敲出双声，听取试灯妆阁。"]},{"t":"东风第一枝 辛己人日，斋宿翰苑，烛花璨然。为拈此解","f":"古风","c":["眼缬迷烟，唇朱缀蜡，依稀光透帘幕。","乍疑锦羽衔来，未许绀纱障却。","娇春稚蕊，有归院、金莲人约。","向夜阑、小簇疏红，怡认半簪梅萼。","试照影、一枝暗托。","待破冷、数椒尚弱。","任他芳信天街，二十四番唤觉。","阳和未准，但背倚、银屏斜角。","尽化作、粉翅双蛾，飞趁玉堂铃索。"]},{"t":"更漏子 庚辰元夕同陈小云一解","f":"古风","c":["锦街灯，灯市雪。","还是消魂时节。","罗幌底，绣屏中。","春寒四面风。","兰釭灺。","春明话。","一十二回元夜。","今昔恨，去来时。","去年人未知。"]},{"t":"更漏子","f":"古风","c":["酒边心，心上事。","信杳故园千里。","心易醉，酒难醒。","夜阑灯晕生。","欣相见。","愁相盼。","明月今宵恨满。","君镜水，我金梁。","梦来谁短长。"]},{"t":"芳草渡","f":"古风","c":["朝非雨，暮非云。","云如絮，雨如尘。","百花时节闭重门。","花有约，春有恨，最愁人。","诉春怨。","春又半。","袅袅晴丝一线。","怜春瘦，为花颦。","花一片。","飘得断。","是春魂。"]},{"t":"好事近 纸鸢","f":"古风","c":["片羽又青云，摇扬半天春色。","莫羡儿童牵引，怕东风无力。","微茫纤绠系虚空，远影定谁识。","偏是绿杨烟外，有流莺窥得。"]},{"t":"绛都春 秦敦夫前辈出所藏冒辟疆姬人金玥美人蕉画册索词","f":"古风","c":["风光几信。","尽描出雉皋，当年花韵。","自剪翠绡，点笔曾看攲蝉鬓。","碧腴乍展痕犹嫩。","似人影、单衫红衬。","染香亭上，凭谁递与，画栏芳讯。","吟稳。","蕉窗秀句，问名字、尚见金明玉润。","素月半规，小篆盈盈芳心印。","螺青写叶春来恨。","认水绘、凄凉眉晕。","任教重觅泰淮，旧时艳粉。"]},{"t":"荷叶杯","f":"古风","c":["忘了梅花憔悴。","乡思。","休更托微波。","翠禽枝上好音多。","无奈客愁何。","闻道章台人去。","飞絮。","风影太天斜。","乱红门径闹蜂衙。","门外是谁家。"]},{"t":"荷叶杯","f":"古风","c":["酿得春光如醉。","清泪。","无赖湿愁红。","为谁香阁掩芙蓉。","山枕倚重重。","迤逦清明时候。","依旧。","烟雨暗芳辰。","晓窗天色近黄昏。","同是梦中人。"]},{"t":"南乡子 宜子孙洗","f":"古风","c":["壁月巧摹形。","土晕铜花别漾青。","砚北何人频拂拭，轻轻。","涤尽霜毫句未成。","小篆认分明。","芳草宜男偶将名。","一例螽斯闻好语，盈盈。","水拍银盘弄化生。"]},{"t":"南乡子 和小云立秋之作","f":"古风","c":["扇影尚依依。","秋到梧桐第几枝。","天上西风凭问讯，来迟。","且为清阴立少时。","筠管强裁诗。","可有微凉入鬓丝。","昨日情怀今夕梦，寻思。","闷里闲中各自知。"]},{"t":"玲珑四犯 虎丘春泛图，为张初白题","f":"古风","c":["烟柳回塘，飏画桨声中，签翠低展。","客与香迷，一舸镜澜徐转。","莺语燕语难分，但醉倚、好花人面。","数旧游彭蠡舟系，忘了小姑偷眼。","四愁平子吴歈遣。","漫沈吟、玉楼歌按。","越娥佩响从归去，春共横波远。","空付媚粉暗尘，荡冶叶、倡条零乱。","问半眉山色，船唇篷背，黛痕谁见。"]},{"t":"喜迁莺 珠巢街新居，古藤交枝，冷翠欲滴，词以赏之。余在都门，凡四移居矣","f":"古风","c":["六街尘外，唤蜡屐问春，春应还待。","娥月迎门，娟枝窥户，吟破一庭苍霭。","簟纹乍移苔点，栏角斜牵萝带。","寄情处，倚新声多幸，莺邻堪买。","空怪。","槐苍里，灯晕梦回，早是圆阴改。","客与琴孤，家如舟泛，秋影几丝同载。","试将冻蜂催醒，有约浓花须再。","倦游宴，念双藤旧侣，题襟谁在。"]},{"t":"喜迁莺 崇效寺看牡丹，时余外转西川，脂车有日矣","f":"古风","c":["只园春霁，借春艳酿成，天然罗绮。","铃语微闻，衣香初染，几度竹房联袂。","瑞蝉又兼金蝶，一样新来梳洗。","话京洛、任寻芳年少，胭脂留醉。","凝睇。","经院悄，疏箔翠油，谁与相料理。","花雨轻沾，珠林低护，还是玉栏愁倚。","靓妆汉宫空赏，归梦瑶台仍寄。","露华冷，赠东风但有，相思红泪。"]},{"t":"六丑 早春晴暖，落灯后风雪凄然，藤蔓欺寒，花事殊寂寂也","f":"古风","c":["唤幽禽梦醒，问急响、花铃谁掣。","试晴扇香，香心如倦蝶。","弱翅犹怯。","暗想西园事，镜中孤影，叹好春难折。","凄风夜半吹还彻。","细糁游尘，斜迎舞雪。","长条冻添冰缬，又因循错过，灯市佳节。","寒宵情切，按清歌乍关。","待向朱栏底，寻步屧。","而今怕理吟箧，任红迟露萼，绿抛烟荚。","探芳景、俊游空说。","都则把、艳冶年光付与，恨眉啼睫。","金觞御，己是愁结。","那更堪、听取银云外，孀娥吊月。"]},{"t":"一枝春","f":"古风","c":["珂里新晴，试清游、过却愔愔坊陌。","欢期暗数，艳景易成陈迹。","旗亭唤酒，倩评跋、好春颜色。","吟遍了，紫曲尘香，惟是燕莺曾识。","幽兰素芬堪摘。","怕东风、认作寻常标格。","琴心倦倚，梦里水波空碧。","何人寄语，但花外玉箫知得。","重看取、小字银钩，冷绡翠拭。"]},{"t":"瑞鹤仙 四月六日出都，小憩芦沟桥偶述","f":"古风","c":["柳丝征袂绾。","试锦羽初程，玉骢犹恋。","铜街佩声远。","向天边回首，故人如面。","藤阴翠晚。","但怪得、琴尊梦短。","有游蜂、知我心期，刚是褪红曾见。","还看。","珠巢题字，墨晕初乾，酒痕微泫。","晴云乍展，春已在，驿桥畔。","问柔波一样，仙源流下，为底人间较浅。","要重寻、京邑尘香，素襟漫浣。"]},{"t":"青山湿遍","f":"古风","c":["瑶簪堕也，谁知此恨，只在今生。","怕说香心易折，又争堪、烬落残灯。","忆兼旬、病枕惯懵腾。","看宵来、一样恹恹睡，尚猜他、梦去还醒。","泪急翻嫌错莫，魂销直恐分明。","回首并禽栖处，书帏镜槛，怜我怜卿。","暂别常忧道远，况凄然、泉路深扃。","有银笺、愁写瘗花铭。","漫商量、身在情长在，纵无身、那便忘情。","最苦梅霖夜怨，虚窗递入秋声。"]},{"t":"西湖月","f":"古风","c":["双鱼诉尽愁肠，又诔笔赢来。","谢庄新句。","为君振触，残春梦影，少年心绪。","何戡今好在，问记否、牵萝人最苦。","但剩得、锦瑟哀辞，题到泪珠圆处。","相看紫诰匆匆，反输与鸿妻，白头荆布。","槿花开也，韶光一刹，等闲朝暮。","长贫长有恨，更忍听、冤禽枝上语。","尽消受、燕寝凝香，旧情空负。"]},{"t":"玉漏迟 重示已生","f":"古风","c":["旧弦催怨轸。","十年前事，翠凋红陨。","幻影分明，忆得镜签香润。","当日啼莺梦远，更此日、啼鹃声近。","愁绪引。","与君原是，一般长恨。","绣帷仿佛尘凝，叹锦字谁传，彩鸾芳信。","病枕叮咛，有约再生重认。","待说韦郎絮果，又怕见、潘郎丝鬓。","清泪忍。","安排半衾眠稳。"]},{"t":"沁园春 题亡室沈淑人遗照","f":"古风","c":["描出伤心，月悴烟憔，回肠怎支。","忆香消玉腕，愁停针线，病淹珠唾，怯试枪旗。","命薄难留，魂柔易断，当日欢场已早知。","良工笔，为传神个里，欲下还迟。","离箱粉缟空思。","剩倩影、幽房一帧携。","看湘兰婀娜，重拈恨蕊，吴绡宛转，未了情丝。","缓缓花开，真真酒暖，环佩归来可有期。","无眠夜，礼金仙绣像，记否年时。"]},{"t":"沁园春 雨夜叠前韵","f":"古风","c":["如此清宵，雨雨风风，更长自支。","想云波涨晓，寒侵素袜，花魂泣夜，怨入灵旗。","阆苑烟凉，瑶台玉瘦，莫道人间总不知。","淋铃苦，怅灯前坐久，帐里来迟。","相逢待诉相思。","但跨鹤、仙山袖便携。","奈杭州衫色，空沾酒晕，河阳帽影，尚恋愁丝。","绛蜡双心，红霞一口，君问归期未有期。","知何日，是香盟证处，好梦圆时。"]},{"t":"沁园春 沈三华龄自常熟买舟来问姊病，人天怅隔，悒怏遂归，赋此为别","f":"古风","c":["归也悽然，迤逦垂虹，孤帆夜深。","问匆匆草草，伊人何许，生生死死，此恨焉任。","卢橘年华，黄梅节物，但著思量总不禁。","离筵曲，有檀郎怨笛，媭女芒砧。","鸣珂旧里重寻。","漫忘却、东阳费苦吟。","叹楼头跨凤，难追彤管，门前立鹄，犹滞青衿。","往事谁提，先芬好念，月姊当时一片心。","还知否，自春明话别，盼到而今。"]},{"t":"沁园春 重赠沈三弟","f":"古风","c":["弹指秋来，已矣荀香，兰房罢薰。","怅官斋寄榻，三春药里，贫家赁庑，廿载飙轮。","象服空埋，牛衣宛在，至竟黔娄是恨人。","重回首，话凄凉旧事，梦去无痕。","依然华屋生存。","恰近隔、山丘只一尘。","看流光过眼，何今何古，抟沙放手，谁幻谁真。","末路荣华，他乡骨肉，自闭重泉杳不闻。","伤心语，但人生到处，天道休论。"]},{"t":"陌上花","f":"古风","c":["烧槽断后来迟，醉舞丽情空采。","旧谱新声，同是梦中虚籁。","诔词凄绝家山破，何止雕栏春改。","趁星期、惯见蕙炉烟影，绛河斜带。","黯银屏、未冷西风吹处，怨入蓉裳荷盖。","半玦潸痕，却倚翠眉先贷。","凭肩已自伤心煞，那复而今能待。","问黄姑、看取穿针楼下，袖罗谁在。"]},{"t":"月下笛 晨起钱塘门乘小舟沿绿至苏公祠","f":"古风","c":["野艇摇烟，生衣蘸渌，镜波圆折。","湖菱翠贴。","最苦新凉犹怯。","话离愁、髯仙未知，雨花露蕊凄步屧。","渐娇云堕砌，芳魂冉冉，暗窥窗月。","柔乡恋否，枉荐菊泉荒，冷香栖蝶。","三生净业，试与长眠人说。","算年来、红尘倦游，好山画里缘再结。","黯消凝，又早芦湾，梦落秋半雪。"]},{"t":"浣溪沙 七月十二日移沈淑人遗榇，于苏公祠却归宝祐桥，回望孤山，黯然久之","f":"七言古诗","c":["路近西陵易怆神。","一袈裟地许平分。","玉棺好伴魏城君。","风月有缘成错莫，湖山如梦断知闻。","烛灰香冷自温存。"]},{"t":"桂殿秋","f":"古风","c":["生死路，去来身。","一杯还酹画中春。","人间大有忘情处，长日恹恹我共君。"]},{"t":"柳梢青","f":"古风","c":["梦了华胥，屏闲翡翠，佩杳珊瑚。","野径双湾，秋祠十笏，门掩菰蒲。","汴河衰柳啼乌，叹旧业、梁园半芜。","瘗玉梅根，眠香桂蕊，好个西湖。"]},{"t":"柳梢青","f":"古风","c":["唤侣鸥凫，者番赢得，尘外嬉娱。","越女开签，黄妃礼塔，纤袂风扶。","段家桥畔幽居，但想像、明珰翠襦。","峰约仙眉，波平佛面，好个西湖。"]},{"t":"柳梢青","f":"古风","c":["酒债诗逋，三年蜡屐，一笛蘋渔。","风景依然，桥将魂断，山拟人孤。","烟波渺渺愁余，且休问、今吾故吾。","萍梗家乡，梅花眷属，好个西湖。"]},{"t":"翠楼吟","f":"古风","c":["箧冷脂函，窗闲粉拂，帘钩静摇霏雾。","金飔锵翠竹，是谁在虚廊微步。","芳踪偷溯。","认暖玉攲闲，横波窥户。","依然误，剪刀声里，唤人鹦鹉。","几度。","风外吟香，搅断魂飘落，一篝花絮。","娇啼惊梦觉，碎珊枕愁红千缕。","钗虫垂处。","盼晓月吹来，仙裙留住。","离情诉。","锦屏深掩，不教飞去。"]},{"t":"花心动 壁间去冬消寒图小幅，状态遗迹也，感赋","f":"古风","c":["芳信冬闺粉梅梢，年时倦怀曾托。","絮雪乍飘，葭管闲吹，刚是病腰如削。","画中疏影人同悴，但长日、秦篝偎著。","倒纤指，因循误了，试灯妆阁。","九九光阴似昨。","空小笔花枝，泥他屏角。","麝炷泪淹，猩点脂融，孤负晓窗梳掠。","酽寒消尽春心死，枉冰蕊，描成红萼。","杏香冷，低回燕莺旧约。"]},{"t":"梦芙蓉 苏祠水榭晚荷，用梦窗韵","f":"古风","c":["方塘馀恨绮。","借微波占住，水仙乡里。","画船双桨，来去锦云外，闹红秋易醉。","多情稳护鸳被。","正好幽栖嗟，冰蜍雾掩，香冷又惊起。","指点回栏近底。","佳约重寻，那处湘皋佩。","露珠娇脸，依旧泪痕洗。","镜澜空晚翠。","吴歈谁解人意。","困倚残妆，但盈盈望远，肠断影娥水。"]},{"t":"霜叶飞","f":"古风","c":["佛天空诉。","姑思曲，青闺遗恨重谱。","几回箴管呼鸡鸣，傍翠屏微步。","怪一榻、缠绵絮语。","催归频指西来路。","向夜月幽房，早卸翅、衔珠臂饰，惨黛偷聚。","人静绣幕低垂，纤裳手挽，暗怯猩点濡缕。","枉将心事祝灵香，奈返魂无据。","看掩抑啼妆最苦，人间真有痴儿女。","染泪痕、栏干外，认取明年，杜鹃红处。"]},{"t":"倒犯 中元","f":"古风","c":["漏点、听岩城渐移，翠林烟袅。","香花缥缈。","圆铃唱、梦魂惊觉。","瑶台上步、秋影绡衣归来好。","叹鹫岭尖风，月冷空相照。","馔伊蒲、几人到。","箫鼓画船，黯黯湖堤，回肠还自绕。","路转背雉堞，兔华落，羊灯悄。","念宋玉、愁多少。","待殷勤、题笺传远道。","奈旧约参差，一夜兰盆倒。","纸钱飞去了。"]},{"t":"金菊对芙蓉","f":"古风","c":["山渌栖烟，城阴卧水，半湖冷画秋容。","奈湖波清浅，不似秋浓。","多情风信天边下，问故人、何处芳踪。","佩声依约，知他见否，月桂香中。","追念往事朦胧。","早齐纨泪黦，并剪尘封。","过虚堂悄悄，履踪谁同。","思君只有兰衾梦，但梦来、未抵相逢。","向无眠夜，金徽怨曲，弹与疏蛩。"]},{"t":"洞仙歌 圣因寺僧馈食","f":"古风","c":["斋厨食品，乍分来莲座。","小舫清芬浪花破。","叹留宾、事往解菜心孤，浑不管，几日芳卮尘锁。","宣南人好在，绥款玫砧，隽味频烦玉纤和。","一箸冷吴羹、雀疃鲈亭，但闷里、秋光虚过。","问书信、麻姑近谁传，料脯擘、仙麟未应忘我。"]},{"t":"金缕曲 湖上得王堶书","f":"古风","c":["倦枕荒祠托。","展苔笺、羊车叔宝，寄情绵邈。","读罢西泠烟波冷，顿尔衣宽带索。","忍重溯、芳仪钟郝。","白奈簪霜惊秋早，惹吴娘、泪为天孙落。","人去也，晓风恶。","前期箫凤悲京洛。","最堪怜、娇花稚蕊，等闲飘泊。","麦饭棠梨城南寺，一样优昙梦觉。","更休问、中年哀乐。","地久天长无时尽，判伤心、与汝今生各。","鸾鉴影，尽抛却。"]},{"t":"清平乐","f":"古风","c":["曲琼风细。","寂寞帘垂地。","消得西堂烟一穗。","随分闲眠浅醉。","象床罗簟关情。","梧桐叶叶秋声。","还向人间惆怅，不知几日浮生。"]},{"t":"二郎神 以亡室所礼水月大全像施圣因寺","f":"古风","c":["绀纱幔卷，尚拂面、穗烟轻飏。","记锦轴薰香，圆仪窥粉，不许蛛丝罥网。","丈室天花成何事，但做尽、人间惆怅。","怜玉骨渐消，金经犹诵，雪衣空葬。","凝想。","西湖去后，月轮无恙。","问幻劫匆匆，相思铅水，可似铜仙露掌。","夕磬听残，晓钟敲罢，谁见妙莲曾放。","霜镜展、剩有凌波翠履，夜深来往。"]},{"t":"花犯 杭署古梅数株，已看花三度矣，顷有桂藩之移，买舟将发，树若有情当为我怅惘也","f":"古风","c":["古墙阴，苔枝卧晚，年华迅弹指。","倦怀谁寄。","怜伴我多情，姑射仙袂。","鉴池画舫寻常系。","珠尘随步绮。","任领略、一庭香雪，栏干花外倚。","而今问春去何之，无端又洒上，天涯别泪。","春去远，空赢得、翠禽憔悴。","停桡待、倩魂未醒，人事与、韶光俱逝水。","付半枕、玉蟾霜影，罗浮清梦里。"]},{"t":"庆春宫 余将去杭，属安之弟率儿子送淑人柩归里前夕宿湖上作","f":"古风","c":["虚阁留仙，孤檠衔梦，旧欢忍问槐柯。","寥落羁魂，踟躇遥夜，半输初泛金波。","未圆先缺，最愁见、亭亭素娥。","残霞吹尽，南北高峰，依约双螺。","秋衾信宿烟萝。","已蜕吴蚕，犹恋修蛾。","天际含颦，云中飞佩，更堪此日离歌。","砌蛩吟苦，替人唤、樽前奈何。","相怜无计，看取青衫，泣下谁多。"]},{"t":"多丽 八月十三日新关道中","f":"古风","c":["古钱唐，翻成此日凄凉。","薤歌中、灰飞纸蝶，褊褼吹上牙樯。","峭帆风、迎来柳，离筵语、递入椒浆。","绿蜡凝愁，素帷搴怨，更无人影到船窗。","叹吾谷、旧山云树，归计苦参商。","经行过、女坟湖水，泪洒吴阊。","问从今、关河万里，可堪重著思量。","鲍家诗、繁台夜雨，江淹恨、岭峤秋霜。","西去啼乌，南征哀雁，断魂容易便分行。","愿留取、镜盟钗约，心字各焚香。","尘缘了，与君携手，片月金梁。"]},{"t":"祝英台近","f":"古风","c":["绾兰襟，搴蕙带，春事问湘畹。","一叶帆收，寒信落灯浅。","怪他宴罢遨头，杯停婪尾，才稳宿、玳梁双燕。","梦绿短。","弹指廿七年华，匆匆去如箭。","依约前欢，人共楚云远。","仲姬小字亲题，金相玉润，怎忘得、那回初见。"]},{"t":"祝英台近","f":"古风","c":["袅朱丝，缠翠缕，巧篆俪花叶。","结就同心，钗股鬓蝉贴。","自从弄玉箫吹，经旬双笑，早一朵、榴红堪折。","扇纹摺。","因甚露井银瓶，馀芬易消歇。","剪烛深更，影事懒重说。","最怜雨润梅黄，袜罗归去，又刚是、澡兰时节。"]},{"t":"祝英台近","f":"古风","c":["典荆钗，搜荩箧，排闷苦无计。","袖薄欺寒，修竹暮长倚。","便教红灺兰釭，相怜相惜。","暖不到、笼鸳秋被。","桂香里。","亲解半臂吴绫，回身为郎系。","染柳宫袍，珍重总输尔。","旧箱金缕空存，此情记否，枉赢得、一襟清泪。"]},{"t":"祝英台近","f":"古风","c":["舞长沙，回短袖，清节一钱剩。","黄竹箱携，絮雪贮秋影。","定知挽鹿偕归，筼屏学绣，恰映月、囊萤相称。","素心耿。","无奈翠履银珰，青闺倦持赠。","女伴偷看，椎髻齿空冷。","更禁嫌到笼鹦，吠来仙犬，生做就、茜窗人病。"]},{"t":"祝英台近","f":"古风","c":["掖垣深，乡信阻，宫漏几昏晓。","缓缓行云，天际忽飞到。","两年怨绿啼红，衔悲饮恨，算客邸、何曾知道。","语声悄。","还认再世相逢，愁多减欢笑。","炊玉光阴，但说凤城好。","为伊闲整湘裙，重温腰衩，更持比、旧时宽了。"]},{"t":"祝英台近","f":"古风","c":["掩金觞，横玉箸，生怕别离又。","听到骊驹，还是絮飞骤。","惯消车毂牵魂，鞭丝摇梦，对残月、晓风杨柳。","断肠后。","凭问此度分襟，重泉尚知否。","飘瞥灵衣，天半枉回首。","早知槿艳无多，便应日日，向纸阁、芦帘厮守。"]},{"t":"祝英台近","f":"古风","c":["舞山香，翻水调，檀板为谁拍。","小谱亲题，曾倩画眉笔。","几回月上雕栏，停针倦绣，闲听我、梅边吹笛。","粉奁侧。","当日藤角裁笺，脂痕尚沾湿。","红豆重拈，乐事总陈迹。","待凭曲里哀蝉，仙山飞去，替说与、酒醒今夕。"]},{"t":"祝英台近","f":"古风","c":["剑江云，犀浦雨，长日药炉近。","侍疾维摩，灯背峭寒忍。","夜阑细检刀圭，偷祈瓦卦，都不是、等闲情分。","蜀鹃恨。","颠倒瓶钵依然，人先散花陨。","瞥眼荣枯，天意杳难问。","那回准拟相如，茂陵遗草，待访取、远山眉晕。"]},{"t":"祝英台近","f":"古风","c":["雀环孤，鸾镜冷，心事竟谁托。","乞与檀奴，跳脱手亲著。","泪痕点点斑斑，凭君认取，想犹记、并肩曾约。","信音邈。","还是翠袖分携，圆规铸成错。","钗合盟言，缥缈碧天阁。","任教赠恨羊权，腕栏双系，拦不住、江南花落。"]},{"t":"祝英台近","f":"古风","c":["净慈香，灵隐愿，瘦骨不胜把。","梅蕊消寒，看到药栏卸。","可怜娥月西颓，清光就缺，又紫玉、烟痕惊花。","病深也。","那更窈窕萦怀，琼瑰渍罗帕。","几日相迎，双影素鸾跨。","竟床长簟凄凉，孤眠剩我，反输尔、夜台情话。"]},{"t":"最高楼","f":"古风","c":["微吟罢，我亦去钱唐。","宦海路茫茫。","春寒容易吴蚕死，秋风依旧越禽忙。","酒鳞边，灯影背，细思量。","且莫说、长安萝补屋。","更莫忆、长沙人倚玉。","尘世事、总堪伤。","孤衾不暖残年梦，征衣空叠旧时香。","算前途，须忍泪，过潇湘。"]},{"t":"十拍子 重过湖上","f":"古风","c":["缺月闲寻昨梦，圆波错认吾乡。","万点沤珠参佛果，一瞬天花作道场。","清钟声未忘。","锦鹢浮生忍托，哀蝉冷句重商。","见说残秋如过客，从此高楼傍夕阳。","归人归路长。"]},{"t":"十六字令","f":"古风","c":["天。","毕竟无情只自圆。","谁传语，花月要相怜。"]},{"t":"十六字令","f":"古风","c":["天。","多事蟾钩要上弦。","从何缺，只为有团栾。"]},{"t":"十六字令","f":"古风","c":["天。","惯把情缘作幻缘。","无人会，生死苦缠绵。"]},{"t":"醉花间 道光丁未二月朔，抵家作","f":"古风","c":["一叶扁舟初著岸。","荷衣今始换。","惭负素餐诗，忍饱田家饭。","犁锄身未惯。","刍豆恩犹恋。","玉京知近远。","隔河一十四邮亭，望东华，长在眼。"]},{"t":"好事近","f":"古风","c":["一榻寄吟身，燕子频窥帘隙。","欲问南村花柳，恨孤筇无力。","等闲窗外雨疏疏，幽径藓痕湿。","忍对浓春烟景，说西风消息。"]},{"t":"一萼红 衎石同年赠杏花二枝，媵以妙词，依调赋谢","f":"古风","c":["浣征衣。","叹缁尘满眼，无处认芳菲。","隔巷遥传，迎门一笑，还似阆苑初移。","展方絮、新声自谱，赏心事、饧白粥香时。","枚馆清愁，蠡湖归梦，此意谁知。","曾是曲江开好，甚珍丛折取，怨别琼枝。","斐几藏春，银瓶寄艳，深护金屋娇姿。","算犹胜、封姨暗剪，掩红泪、轻逐燕莺飞。","旧日名园倚处，莫寄相思。"]},{"t":"子夜歌","f":"古风","c":["剡溪笺、一编行记。","荏苒岁华重省。","寄情处、南船北马，好句为谁题赠。","山馆琴樽，河桥风月，那复伤萍梗。","但相看、鸿爪馀痕，还是简书，周道寸心堪证。","试偻指、天涯旧迹，几度雨昏烟暝。","岷葛吴莼，蛮花郢雪，过影仍留影。","尽含宫嚼徵，侵寻霜鬓吹冷。","倦羽归飞，片帆催卸，才始吟魂定。","按新声、小拍红牙，唤教梦醒。"]},{"t":"庆春宫 题仇实甫《汉宫春晓图卷》","f":"古风","c":["野雉亡来，哀蝉吟后，汉宫别样春光。","玉树周阿，金釭衔壁，粉云浮动花香。","舞裙留住，趁殿角、西风未凉。","班姬何许，空裂齐纨，掩袂情伤。","繁华过眼沧桑。","沙麓元城，妖谶难防。","传诏纷驰，持弓栏入，做成文母祯祥。","仲卿书奏，累长信、轻抛泪行。","谁移炎祚，休说当时，祸水昭阳。"]},{"t":"浣溪沙","f":"七言古诗","c":["近市翛然晏子居。","药栏回合槿篱疏。","惯看鸟雀下阶除。","载酒断无人问字，打门恰有吏催租。","到家翻遣客怀孤。"]},{"t":"浣溪沙","f":"七言古诗","c":["花落花开正掩门。","忘机不识绕街尘。","寂无馀事称闲身。","梁燕依然同逆旅，邻莺争解唤乡人。","悔将心迹托归云。"]},{"t":"浣溪沙","f":"七言古诗","c":["旧侣分张唤奈何。","凉秋无梦到烟萝。","独弦弹断不成歌。","眼底曹蜍生气少，耳边庄蝶寓言多。","此情容易隔天河。"]},{"t":"浣溪沙","f":"七言古诗","c":["客有君房妙语言。","扬州骑鹤兴翩翩。","倾身障簏总堪怜。","情话漫寻潘骑省，清芬谁诵陆平原。","闷思陈事一悽然。"]},{"t":"浣溪沙","f":"七言古诗","c":["酸枣河倾忆昔时。","洪波吟得阮公诗。","十年风景几迁移。","暗草萤飞仓史墓，阴廊鬼语信陵祠。","等闲牲醴祀屠儿。"]},{"t":"浣溪沙","f":"七言古诗","c":["词赋梁园久劫灰，游人还问孝王台。","多因帝子解怜才。","咫尺僧寮环塔址，两三村舍傍城隈。","已无馀地馆邹枚。"]},{"t":"浣溪沙","f":"七言古诗","c":["软绣天街旧有名。","九君传序费经营。","至今犹说宋东京。","一穗冷烟春锦阁，半湾流水翠芳亭。","上河图画不胜情。"]},{"t":"浣溪沙","f":"七言古诗","c":["玉树琼枝感旧因。","教坊歌罢暗伤神。","不堪洗面藉潸痕。","青盖辞吴犹怆恻，华亭入洛尚酸辛。","重瞳那作汴州民。"]},{"t":"浣溪沙","f":"七言古诗","c":["金字心经施上方。","澄心遗积付沧桑。","累他嫔御祝空王。","春水东流如梦寐，秋风西塔剩凄凉。","一花垂泪佛前香。"]},{"t":"浣溪沙","f":"七言古诗","c":["三黜何劳赋谪居。","芝兰香冷寸心孤。","鸡鸣草草岁云徂。","勇退漫思绵上隐，生存休问茂陵书。","紫垣还记旧人无。"]},{"t":"浣溪沙","f":"七言古诗","c":["乐府东都迥出尘。","小山以后数清真。","风流秦贺足消魂。","桥柱枉逢题字客，旗亭无复按歌人。","懒邀明月认前身。"]},{"t":"浣溪沙","f":"七言古诗","c":["十载宣南梦里家。","珠巢弹指即天涯。","可知宫树不栖鸦。","一榻沈吟淇上竹，数枝憔悴洛阳花。","冷筇闲倚望京华。"]},{"t":"女冠子","f":"古风","c":["蜺旌珠箔。","咫尺五云楼阁。","望参差。","蓬岛千龄药，华阳十赉辞。","传情金带枕，倚醉玉交卮。","不是鹦哥语，有谁知。"]},{"t":"蝶恋花","f":"古风","c":["祷雨灵坛烟篆细。","甘露金瓶，几滴耕夫泪。","眠梦阿香醒也未。","焦原渴望雷车至。","蜥蜴曾无窥管智。","一纸官符，入瓮难回避。","绣阁丹砂需点臂。","虫虫管甚闲公事。"]},{"t":"减字木兰花 凉棚","f":"古风","c":["杉竿几柱。","细篾疏筠相绾住。","小簟微凉。","不许西楼到夕阳。","轻阴夏五。","底事梅炎偏易雨。","雨亦堪听。","画舫江南忆此声。"]},{"t":"太常引","f":"古风","c":["尘沙拂面阻清游。","长日下帘钩。","谁倚钿箜篌。","尽弹出、新愁旧愁。","朋尊冷落，诗怀潦倒，排闷强登楼。","风柳一枝秋，认当日、烟花汴州。"]},{"t":"烛影摇红 己酉元夕","f":"古风","c":["三五良宵，乞浆且喜年逢酉。","只今无复万枝灯，也自游骢骤。","迤逦瑶街左右。","闹蛾儿、盈盈茜袖。","玉梅香暖，爆竹烟深，听残莲漏。","春日春盘，翠尊不用清歌侑。","等闲留住月婵娟，相伴啼鸦后。","屈指韶光暗逗。","尽安排、寻花问柳。","凤箫声里，愿得年年，欢娱依旧。"]},{"t":"斗百草 荼蘼作花甚盛，词以赏之","f":"古风","c":["薄暖庭阶，渐长天气韶光老。","阆苑移根，翠阴压架，千朵粉云细袅。","认幽姿、恰净洗铅华，天然娟妙。","更嫩蕊含风，浓芬裛露，伴人清晓。","还是寻香蝶趁，摘艳蜂忙，那说一年花事了。","梨梦酣馀，柳绵飘尽，宴飞英、芳尊自倒。","渊明语，得称心时固为好。","漫相恼。","任西园、杜鹃唤早。"]},{"t":"锦堂春慢","f":"古风","c":["葵藿孤生，菰芦槁项，十年重踏京尘。","幸天涯萍梗，握手情亲。","往事倾谈未尽，清愁别袂仍分。","算虹桥路迥，鹤盖阴浓，难著闲身。","镜蓉佳谶应准，但骊驹催唤，欲住无因。","望切泥金好语，早寄衡门。","射策君宜上第，看花我愧陈人。","问新莺队里，旧曲谁知，山抹微云。"]},{"t":"曲游春 道旁短垣中，绯桃余花数朵，妍媚可悦，如使移植都门，必当忙煞游春车亦","f":"古风","c":["一水疏篱映，见小桃朱朵，墙角低亚。","丽质天生，甚芳根偏寄，冷烟茅舍。","休问量珠价。","梦不到、玉楼琼榭。","尽露华、啼湿东风，肯学杏红偷嫁。","妍雅。","幽怀暗写。","似空谷佳人，尘外潇洒。","可惜啼鹃，唤仙山归去，倩妆轻卸。","嘶骑闲门下。","更谁记、乞浆馀话。","无奈燕麦元都，为伊恨惹。"]},{"t":"木兰花慢 咏柏乡店舍柳","f":"古风","c":["怪当门细柳，见行客、似依依。","记檀板徵歌，金尊唤酒，翠绕香围。","芳菲。","舞腰倦倚，正三眠三起泥人时。","消得天涯别恨，渭城一曲新词。","凄其。","花月旧情非。","烟穗只低垂。","叹寻春年少，何人解忆，当日颦眉。","禁持。","峭风暗剪，便章台瘦尽有谁知。","指点黄昏院落，暝鸦飞上空枝。"]},{"t":"徵招","f":"古风","c":["北山偶尔停云出，匆匆暂分吟袂。","话别未移时，早嘤鸣人逝。","旧盟今剩几。","忍重溯、紫垣遗事。","四十三年，澹烟清梦，暗飘灯穗。","弃置竟何心，江乡路、难寻狎鸥闲地。","千卷史公书，尽周南留滞。","卜居辞漫拟。","已零落、蕙纕兰佩。","广陵散、一曲哀弹，叹古音谁嗣。"]},{"t":"双双燕 咏燕","f":"古风","c":["柳塘杏苑，认当日轻盈，汉宫姝丽。","斜风一剪，弄影爱寻罗绮。","久住芹泥旧垒，又贪说、乌衣门第。","终朝絮语呢喃，那识投怀深意。","前事。","吾庐曾寄。","待小院开帘，更将春至。","翩翩何许，惯向玉楼凝睇。","王谢雕梁任倚，但秋社、光阴能几。","从他锦字传笺，空惹故人清泪。"]},{"t":"满江红","f":"古风","c":["甚矣吾衰，七十载、光阴虚掷。","曾几度、春来秋去，曦轮已仄。","脉脉徒怀尘外想，悠悠终是人间客。","忆东涂、西抹少年时，嗟何及。","鸡与鹜，从争食。","蚌与鹬，从夸力。","但相看一笑，马牛风隔。","长庆诗筒馀昨梦，永和禊饮成陈迹。","叹曹刘、沉谢尽消亡，今谁识。"]},{"t":"河传","f":"古风","c":["锦浦。","佳处。","浣花祠宇。","梅柳成行。","扫眉人去，还见金井丛篁。","绕回廊。","胜游争免天涯感。","衣香减。","羞说缁尘染。","输他仙侣，依旧莲烛分光。","赋长杨。"]},{"t":"河传","f":"古风","c":["湖上。","烟浪。","摇摇画桨。","事逐春移。","兰闺扶病，心绪花落鹃啼。","弄妆迟。","六桥风景成虚掷。","青弯翼。","一去无消息。","水仙乡里，回首玉局荒祠。","断肠时。"]},{"t":"河传","f":"古风","c":["滕阁。","帆落。","烟光澹泊。","山色空濛。","乌监一曲，新谱催唱玲珑。","醉魂中。","落霞孤鹜年光换。","苹沙岸。","寂寞闲鸥伴。","庾尘不到，何事腰扇匆匆。","障西风。"]},{"t":"河传","f":"古风","c":["黄鹤。","城郭。","笛声依约。","吹尽寒梅。","东君有意，还许轻燕飞来。","绣帘开。","个中心事沈吟久。","曾知否。","梦冷鸦啼后。","萍漂一叶，闲倚江上楼台。","暂徘徊。"]},{"t":"河传","f":"古风","c":["岭外。","谁在。","湍流水带。","峭立山簪。","家园春色，空倩幽梦重寻。","瘴云深。","漫拈迁客伤心句。","蛮江渡。","几见人归去。","秦郎已矣，留得子夜哀吟。","古藤阴。"]},{"t":"河传 祝九宗伯枉过戏赠","f":"古风","c":["十弓地小。","遣吟情种得。","寻常花草。","吠影吠声，那禁群儿相告。","说平泉、无此好。","长安贵客心倾倒。","来便窥园，寓目翻成笑。","鸠拙一枝，谁向宫莺传报。","误煞人、秦吉了。"]},{"t":"声声慢 风雨通宵，篱菊损败，感叹成咏","f":"古风","c":["亭亭素艳，恻恻孤芳，禁他风雨摧残。","老圃秋容，争信晚节艰难。","东篱惯招旧隐，记金英、簪鬓曾看。","寻步屧，甚啼螀坏壁，怨语更阑。","还是题糕人在，奈子安序冷，元亮吟悭。","梦远湘皋，谁念楚些哀弹。","重阴望中未解，寄清愁、何处南山。","松径里，愿香心、同保岁寒。"]},{"t":"汉宫春 汝筠率孙辈频年都勇剿贼，今以韶关解围，均获迁秩。感恩述事，赋此寄筠","f":"古风","c":["岭上梅枝，送春风芳讯，直抵吾庐。","陵江一军独进，净扫萑苻。","鸣琴未几，便承恩、五马前驱。","比当日、东山折屐，老怀欣幸奚殊。","恨恨潢池盗弄，奈衰龄蹇足，空守乡闾。","行间代余宣力，赖尔诸雏。","角巾私第，待他年、鸠杖归扶。","还试问、元侯经训，何如黄石公书。"]},{"t":"甘草子 题画：柯丹丘风雨归舟","f":"古风","c":["归去。","一叶扁舟，却问归何处。","衰柳不成行，冷落蒹葭浦。","风利漫歌公无渡。","便萍梗、有时须住。","莫向南村素心侣。","话五湖烟雨。"]},{"t":"留春令 题画：倪云林溪亭山色","f":"古风","c":["小山疏树，墨痕轻染，几重烟翠。","石径萦回一亭孤，倩传出、幽人意。","仿佛前游如梦里。","尚渔舟闲系。","曲港斜通武陵溪，问曾见、桃花未。"]},{"t":"卜算子 题画：王孟端高梧竹石","f":"古风","c":["白石藓纹滋，绿竹烟痕净。","何似崇冈百尺梧，一碧凝秋影。","认是雅琴材，古调无人省。","尽有高枝待凤皇，恻恻天风冷。"]},{"t":"杏花天影 大雨后戏作","f":"古风","c":["官衙潦水频频戽。","似天半、银河灌注。","道南人在下流居，最苦。","小茅庐、避甚处。","门前路回汀枉渚。","尽濡足、依然窘步。","等闲思约故人来，浪语，便无风、也断渡。"]},{"t":"卜算子慢 画帘微雨，追往悼今，率成此解，时咸丰丁巳仲秋六日也","f":"古风","c":["庭阴坠叶，楼外断鸿，振触武林前事。","七载离鸾，梦冷蕙炉烟细。","凝睇，枉思量月没教星替。","奈过眼韶华，一瞬依然春到蓝尾。","草草人间世。","叹两度伤心，百年弹指。","倚瑟双声，信杳碧城十二。","愁悴。","掩孤嚬、闲写银笺字。","待唤取、仙山翠羽，怕深情难寄。"]},{"t":"山花子","f":"古风","c":["闻说张星本在天。","何因解佩向人间。","长记维舟南浦望，月娟娟。","短梦乍酣春枕畔，倩魂无定夜灯前。","懊恨霓裳三十八，数华年。"]},{"t":"谒金门","f":"古风","c":["一叶落。","寂寂西堂帘幕。","桐树心孤生意薄。","非关风信恶。","后夜重寻梦约。","褪尽灯花半萼。","斗帐香囊垂四角。","春情无处著。"]},{"t":"谒金门","f":"古风","c":["裙衩窄。","何意飞龙骨出。","秋社光阴归燕急。","锦衾人似客。","未到中秋十日。","月姊也应悽恻。","宛转玉钩清露湿。","欲圆圆不得。"]},{"t":"谒金门","f":"古风","c":["乡梦促。","花草长洲路熟。","还是烽烟惊比屋。","心伤千里目。","几日蓝田采玉。","几日秦楼吹竹。","消得齐奴珠一斛。","华年如转烛。"]},{"t":"谒金门","f":"古风","c":["妆镜侧。","那见卷衣人立。","撩眼乱红春一色。","争教莺语涩。","道是上清沦谪。","谁问青鸾消息。","帽底霜丝空自惜。","玉箫难再得。"]},{"t":"谒金门","f":"古风","c":["兰畹曲。","赢得凄凉满幅。","苦句今生吟已足。","他生休更卜。","指点山邺华屋。","迅羽轻尘相逐。","蜡炬成灰钟漏促。","断无残梦续。"]},{"t":"莺啼序","f":"古风","c":["鸳帏麝熏顿冷，忍重窥牗户。","梦缘短、花落鹃啼，坐惜长簟催暮。","弄红豆、何人记曲。","回肠宛转相思树。","甚兰房翻似，离亭淡烟飞絮。","屈指频年，故里道梗，尚南天掩雾。","话前事、娥月含嚬，眼穿江上鱼素。","耿无眠、深更漏咽，帕罗湿、愁丝千缕。","枉叮咛，莲舫同游，锦泾鹓鹭。","萍踪暗想，片叶天涯，几回趁雁旅。","鹤去远、笛楼吹罢，夏口遄归，又逐扁舟，陡河听雨。","鸾骖信杳，蜂衙香散，翩然春水凌波袜，唤归禽、柳色甘棠渡。","从看倚竹，牵萝半萼青灯，澹泊肯厌乡土。","安居自适，履迹闲园，待艺庥沤苎。","奈几载、悲笳传恨，病骨攲床，浣泪单衫，退红羞舞。","中秋近也，灵丹无验，优昙开好还易萎，动哀吟、华表谁家柱。","他时青鸟飞回，鬓雪韦郎，倩魂记否。"]},{"t":"愁倚栏令","f":"古风","c":["怜花好，惜花残。","倚栏干。","长向仇英图画里，认家山。","年来瘦损朱颜。","芳心冷，鸾镜羞看。","禁得杏梁双燕子，说春寒。"]},{"t":"愁倚栏令","f":"古风","c":["鸳针歇，画屏闲。","病经年。","可惜天孙云锦样，倩谁传。","罗囊旧绣依然。","无聊赖，尘壁空悬。","争忍看他珠络索，翠连娟。"]},{"t":"河满子","f":"古风","c":["栽得幽花数种，小庭雨腻烟浓。","春自天台移到，人如阆苑相逢。","今日人将春去，露珠啼碎香红。"]},{"t":"河满子","f":"古风","c":["忆昔蒲觞饮后，惊心风鹤来时。","多少朱门绣毂，匆匆絮影分飞。","争似吾家络秀，琐窗闲赌围棋。"]},{"t":"河满子","f":"古风","c":["雅戏闺中裁制，春工幻作春人。","粉壁空留剪彩，玉墀已掩香尘。","莫向紫姑说与，红笺应也销魂。"]},{"t":"醉垂鞭","f":"古风","c":["莫唱望江南。","娃宫柳。","沉吟久。","烟外影鬖鬖。","清霜知未堪。","魂归应恋此。","虚廊倚。","旧香拈。","悄拭藕丝衫。","防他珠泪淹。"]},{"t":"惜双双","f":"古风","c":["梁燕依依成伴侣。","谁遣把、离愁深诉。","江海漫惜归去。","隔后春社还相遇。","独有巫峰天外路。","无计使、行云留住。","三点四点更鼓。","画帘听尽潇潇雨。"]},{"t":"水龙吟 丁己冬仲，俞婿自南康返浙，道出汴城，信宿别去，悒怏累日，赋此以遣闷怀","f":"古风","c":["病馀心事阑珊，英英润玉欣来至。","奚奴传报，马嘶门外，鹊喧檐际。","茸帽冲寒，尘襟浣雪，顿宽离思。","奈停觞语促，倚闾望久，欲留也、浑无计。","枉说灯花太喜。","被春风、等闲吹碎。","春如有约，人应依旧，关河千里。","短烛心灰，归鞍目送，断魂潮尾。","但摧颓一老，殷勤执手，洒临歧泪。"]},{"t":"石州慢 落花","f":"古风","c":["欲雨还晴，春色正妍，游兴方引。","彩幡蓦地飘摇，多事晓风吹紧。","东君薄幸，空负燕约莺期，无端轻送韶华尽。","仙子玉峰来，又催回兰轸。","愁损。","蜀笺题字，吴舫传杯，少年青鬓。","已是凄凉，那更翠凋红陨。","冬郎好句，留下千古伤心，人间易得芳时恨。","忍见葬花人，扫苔阶香粉。"]},{"t":"摸鱼儿 丁煦洲先生索题某司马湖庄福隐图","f":"古风","c":["占幽居、六桥东畔，天然柳港花坞。","书楼掩映窗三面，咫尺翠屏云聚。","携胜侣。","算福地、仙乡最好诗人住。","吟情漫与。","怕竹马迎来，金鱼挽定，未放使君去。","空中想，指点刘郎前度。","盟鸥今在何许。","卅年影事匆匆过，谁访绿苔题句。","清梦阻。","更那得、片帆吹到江南路。","披图认取。","但栏角听莺，船唇载鹤，寻我旧游处。"]},{"t":"阮郎归","f":"古风","c":["绿云鬟倚小桃枝。","盈盈把袂时。","玉箫吹作凤双飞。","春光无尽期。","仙梦短，俗情迷。","翩然一鹤归。","人民城郭是耶非。","伤心丁令威。"]},{"t":"阮郎归","f":"古风","c":["东风吹冷碧桃花。","尘心枉自嗟。","合欢衾外即天涯。","谁教归兴赊。","寻故步，趁丹霞。","仙山路未差。","愿持鸦觜种胡麻。","从今休忆家。"]},{"t":"采桑子","f":"古风","c":["暮笳吹送江南怨，远信模糊。","噩梦踟蹰。","烽火连天照海虞。","旧家门馆知何似，断柳啼乌。","破瓦奔狐。","留得东阳子姓无。"]},{"t":"采桑子","f":"古风","c":["檀郎歌管凄凉曲，叹息清门。","月冷烟昏。","一霎昆明劫后尘。","世间何限伤心事，漫说真真。","早岁离魂。","免得思家积泪痕。"]},{"t":"采桑子","f":"古风","c":["左芬书问经年断，南雁飘零。","又说吴兴。","日夜风传唳鹤声。","昔年避乱栖湖溇，烟水凄清。","今日伶仃。","可许荒湾寄此生。"]},{"t":"更漏子 庚申岁杪，密雪经旬，中庭积厚四五尺，平生所未见也","f":"古风","c":["篆烟沈，灯炷落。","愁掩夜寒帘幕。","天黯澹，路冥迷，征人何日归。","唤春回，春未醒。","谁念玉梅香冷。","残岁逼，暮云深，休听元鹤吟。"]},{"t":"金缕曲 卖宅","f":"古风","c":["燕子闻长叹。","甚匆匆、廿年安宅，梦缘能短。","曾是琴尊游息地，苦被啼莺催散。","且休说、仙源深浅。","洞口云来迷处所，悔当时、只作寻常看。","枉回首、画栏畔。","嫣红姹紫闲栽遍，到而今亭台易主，旧欢空恋。","从此春风无路入，那见小桃人面。","更谁与、金荃歌按。","可惜好花如好婢，向人家、看卖牙郎绢。","重为汝、泪痕溅。"]},{"t":"水调歌头 辛酉三月廿七日，移居文殊寺巷，所谓蜗角蚊睫，又足相容者也","f":"古风","c":["往事过驹隙，末路寄蜗庐。","不知箪食瓢饮，陋巷较何如。","小植红桃绿柳，闲缚茅篱竹栅，幽梦蝶蘧蘧。","朱绂者谁子，门外已过车。","邺侯井，徐稚榻，子云居。","翩然舍去聊可，著论拟潜夫。","昔日天花弹指，今日缁尘满眼。","香界久榛芜，我有数椽庇，犹足傲文殊。"]},{"t":"鹧鸪天","f":"古风","c":["仙侣何因证旧欢。","素屏凉影有无间。","三生石泐情长在，半萼灯孤夜未阑。","蛩语寂，鹤声闲。","片云从此谢尘寰。","凭谁访我栖真地，黄叶萧萧玉笥山。"]}]};